/* Room-only prices: gross CHF per room/night, by adult count and child count.
   Breakfast belongs to the accommodation special VAT rate even if shown separately.
   Extra meals on half/full board are separately billed at the standard rate. */
const VAT_LODGING=3.8,VAT_CATERING=8.1;
const cents=v=>Math.round(Number(v)*100);
const chf=c=>Math.round(c)/100;
function priceInput(value,label,name){return '<label>'+esc(label)+'</label><input type="number" name="'+name+'" min="0" step="0.01" value="'+esc(value===undefined||value===null?'':value)+'" placeholder="Basispreis verwenden">'}
function priceForm(room){
 let out='<section class="price-editor"><h3>Zimmer-Tarife · ohne Verpflegung</h3><p>CHF brutto je Zimmer und Nacht, inklusive 3,8 % MWST. Der Preis für Erwachsene ist der gesamte Zimmerpreis. Der Kinderbetrag ist ein Zuschlag für die angegebene Kinderzahl.</p>';
 out+='<details class="tariff-section" open><summary>Personenstaffel · Erwachsene und Kinder</summary><div class="price-fields">';
 for(let i=1;i<=6;i++)out+='<div class="price-field">'+priceInput(room['adultRate'+i],i+' Erwachsene · Gesamtpreis CHF','adultRate'+i)+'</div>';
 for(let i=1;i<=4;i++)out+='<div class="price-field">'+priceInput(room['childRate'+i],i+' Kinder · Zuschlag CHF','childRate'+i)+'</div>';
 out+='</div></details><details class="tariff-section"><summary>Wochenendtarif · Freitag und Samstag</summary><p>Aufschlag für Freitag- und Samstagnächte in Prozent; 0 bedeutet Standardpreis.</p><div class="price-fields"><div class="price-field">'+priceInput(room.weekendPercent||0,'Wochenendzuschlag %','weekendPercent')+'</div></div></details>';
 out+='<details class="tariff-section"><summary>Saison-Tarife · zwei Zeiträume</summary><p>Datumsbereiche inklusive Start- und Endtag. Positive Prozentwerte sind Zuschläge, negative sind Rabatte.</p><div class="season-list">';
 for(let i=1;i<=2;i++)out+='<div class="season-group"><strong>Saison '+i+'</strong><label>Name</label><input name="season'+i+'Name" value="'+esc(room['season'+i+'Name']||'')+'" placeholder="z. B. Hochsaison"><label>Von</label><input type="date" name="season'+i+'Start" value="'+esc(room['season'+i+'Start']||'')+'"><label>Bis</label><input type="date" name="season'+i+'End" value="'+esc(room['season'+i+'End']||'')+'">'+priceInput(room['season'+i+'Percent']||0,'Anpassung %','season'+i+'Percent')+'</div>';
 return out+'</div></details></section>';
}
function validPricePlan(room){
 for(let i=1;i<=6;i++)if(room['adultRate'+i]!==''&&room['adultRate'+i]!=null&&(!Number.isFinite(Number(room['adultRate'+i]))||Number(room['adultRate'+i])<0))throw Error('Ungültiger Preis für '+i+' Erwachsene');
 for(let i=1;i<=4;i++)if(room['childRate'+i]!==''&&room['childRate'+i]!=null&&(!Number.isFinite(Number(room['childRate'+i]))||Number(room['childRate'+i])<0))throw Error('Ungültiger Kinderzuschlag');
 const percent=Number(room.weekendPercent||0);if(!Number.isFinite(percent)||percent<0||percent>300)throw Error('Wochenendzuschlag muss zwischen 0 und 300 % liegen');
 for(let i=1;i<=2;i++){const start=room['season'+i+'Start'],end=room['season'+i+'End'],p=Number(room['season'+i+'Percent']||0);if((start&&!end)||(!start&&end))throw Error('Saison '+i+': Start und Ende angeben');if(start&&end&&start>end)throw Error('Saison '+i+': Zeitraum ungültig');if(!Number.isFinite(p)||p< -100||p>300)throw Error('Saison '+i+': Anpassung ausserhalb -100 bis 300 %')}
 if(room.season1Start&&room.season2Start&&room.season1Start<=room.season2End&&room.season2Start<=room.season1End)throw Error('Saisonzeiträume dürfen sich nicht überschneiden');
}
function occupancy(b){const adults=b.adults==null||b.adults===''?Number(b.people||1):Number(b.adults),children=Number(b.children||0);if(!Number.isInteger(adults)||adults<1||adults>6||!Number.isInteger(children)||children<0||children>4)throw Error('Erlaubt sind 1–6 Erwachsene und 0–4 Kinder');return {adults,children,people:adults+children}}
function grossRoomNight(room,b,date){
 const occ=occupancy(b),adult=room['adultRate'+occ.adults],child=room['childRate'+occ.children],base=adult!==''&&adult!==undefined&&adult!==null?Number(adult):Number(room.rate||0);
 const children=occ.children&&child!==''&&child!==undefined&&child!==null?Number(child):0;
 if(!Number.isFinite(base)||base<0||!Number.isFinite(children)||children<0)throw Error('Zimmerstaffel ungültig');
 let value=cents(base+children),dt=new Date(date+'T12:00:00Z'),weekend=dt.getUTCDay()===5||dt.getUTCDay()===6;
 if(weekend)value=Math.round(value*(1+Number(room.weekendPercent||0)/100));
 for(let i=1;i<=2;i++){const start=room['season'+i+'Start'],end=room['season'+i+'End'];if(start&&end&&date>=start&&date<=end)value=Math.round(value*(1+Number(room['season'+i+'Percent']||0)/100))}
 return value;
}
function mealQuote(b,hotel){
 const o=occupancy(b),meal=b.meal||'Nur Logis';if(meal==='Nur Logis')return {breakfast:0,other:0};
 const keys={Frühstück:'breakfast',Halbpension:'halfBoard',Vollpension:'fullBoard'},prefix=keys[meal];
 if(!prefix)throw Error('Verpflegung ungültig');
 const adult=Number(hotel[prefix+'Adult']||0),child=Number(hotel[prefix+'Child']||0),amount=cents(adult*o.adults+child*o.children);
 if(!Number.isFinite(amount)||amount<0)throw Error('Verpflegungspreis ungültig');
 if(meal==='Frühstück')return {breakfast:amount,other:0};
 const breakfast=cents(Number(hotel.breakfastAdult||0)*o.adults+Number(hotel.breakfastChild||0)*o.children);
 if(breakfast>amount)throw Error('Halb- und Vollpension dürfen nicht günstiger als Frühstück sein');
 return {breakfast,other:amount-breakfast};
}
/* Kurtaxe: lokale Tarife ohne bundesweit erfundene Vorgaben. Befreiungen je Reservation. */
function validateTouristTax(h){
 if(!['0','1',0,1].includes(h.touristTaxEnabled))throw Error('Kurtaxe aktivieren oder deaktivieren');
 for(const key of ['touristTaxAdult','touristTaxChild']){const v=Number(h[key]||0);if(!Number.isFinite(v)||v<0||v>1000||Math.abs(v*100-Math.round(v*100))>0.00001)throw Error('Kurtaxe: ungültiger Betrag pro Nacht')}
}
function touristTaxQuote(b,hotel,days){
 const o=occupancy(b),exAdults=Number(b.taxExemptAdults||0),exChildren=Number(b.taxExemptChildren||0);
 if(!Number.isInteger(exAdults)||exAdults<0||exAdults>o.adults||!Number.isInteger(exChildren)||exChildren<0||exChildren>o.children)throw Error('Kurtaxe: befreite Personen müssen innerhalb der Gästezahl liegen');
 const enabled=String(hotel.touristTaxEnabled||'0')==='1';
 if(enabled)validateTouristTax(hotel);
 const adultRate=enabled?Number(hotel.touristTaxAdult||0):0,childRate=enabled?Number(hotel.touristTaxChild||0):0;
 const adults=o.adults-exAdults,children=o.children-exChildren,adultAmount=adults*cents(adultRate)*days,childAmount=children*cents(childRate)*days;
 return {enabled,adults,children,exemptAdults:exAdults,exemptChildren:exChildren,adultRate,childRate,amount:chf(adultAmount+childAmount)};
}
function touristTaxSettings(h){return '<section class="tourist-tax-settings"><h2>Kurtaxe / Gästetaxe</h2><p>Die Kurtaxe wird von der Gemeinde bzw. Tourismusregion geregelt. Trage die amtlichen Beträge pro Nacht ein. Kinderbefreiungen und weitere Ausnahmen werden bei jeder Reservation separat erfasst. Standardmässig ist die Abgabe deaktiviert.</p><label>Kurtaxe erheben</label><select name="touristTaxEnabled"><option value="0" '+(String(h.touristTaxEnabled||'0')==='0'?'selected':'')+'>Nein – nicht berechnen</option><option value="1" '+(String(h.touristTaxEnabled)==='1'?'selected':'')+'>Ja – gemäss lokalem Reglement</option></select><div class="price-fields"><div>'+priceInput(h.touristTaxAdult||0,'Erwachsene · CHF pro Person/Nacht','touristTaxAdult')+'</div><div>'+priceInput(h.touristTaxChild||0,'Kinder · CHF pro Kind/Nacht','touristTaxChild')+'</div></div><p class="tourist-tax-notice">Kurtaxe separat ausweisen. Ob sie als durchlaufender Posten ohne MWST behandelt werden darf, muss anhand des lokalen Reglements und der Abgabeschuldnerschaft geprüft werden.</p></section>'}
function extraMealOverrides(b){const result={};for(const line of String(b.extraMealDays||'').split(/\r?\n/).filter(v=>v.trim())){const [day,...values]=line.split(';').map(v=>v.trim());if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!Number.isFinite(Date.parse(day))||new Date(day).toISOString().slice(0,10)!==day||day<b.arrival||day>b.departure||values.length!==3||values.some(v=>!/^\d{1,3}$/.test(v)||Number(v)>100)||Object.prototype.hasOwnProperty.call(result,day))throw Error('Ungültige Tagesabweichung bei Zusatzmahlzeiten');const counts=values.map(Number);if((day===b.arrival&&(counts[0]||counts[1]))||(day===b.departure&&(counts[1]||counts[2])))throw Error('Zusatzmahlzeiten am An-/Abreisetag prüfen');result[day]=counts}return result}
function bookingQuote(b,room,hotel){
 const o=occupancy(b),days=nights(b);if(!Number.isInteger(days)||days<1||days>366)throw Error('Aufenthalt muss 1–366 Nächte umfassen');
 const lodgingDays=[];for(let i=0;i<days;i++){const date=new Date(Date.parse(b.arrival+'T12:00:00Z')+i*86400000).toISOString().slice(0,10);lodgingDays.push({date,amount:grossRoomNight(room,b,date)})}
 const lodging=lodgingDays.reduce((n,x)=>n+x.amount,0),meals=mealQuote(b,hotel);
 const overrides=extraMealOverrides(b);const extra=(key,count)=>{const qty=Number(b[key]||0),price=Number(hotel[key+'Price']||0);if(!Number.isInteger(qty)||qty<0||qty>100||!Number.isFinite(price)||price<0||price>10000)throw Error('Ungültige Zusatzmahlzeit');const index=['extraBreakfast','extraLunch','extraDinner'].indexOf(key);let total=qty*count;for(const [day,counts] of Object.entries(overrides)){const eligible=index===0?day>b.arrival:index===1?day>b.arrival&&day<b.departure:day<b.departure;if(eligible)total+=counts[index]-qty}return total*cents(price)};const extraBreakfast=extra('extraBreakfast',days),extraLunch=extra('extraLunch',Math.max(0,days-1)),extraDinner=extra('extraDinner',days);const breakfast=meals.breakfast*days+extraBreakfast,other=meals.other*days+extraLunch+extraDinner,touristTax=touristTaxQuote(b,hotel,days);
 return {nights:days,people:o.people,adults:o.adults,children:o.children,lodging:chf(lodging),breakfast:chf(breakfast),other:chf(other),touristTax:touristTax.amount,touristTaxDetails:touristTax,extraMeals:{breakfast:chf(extraBreakfast),lunch:chf(extraLunch),dinner:chf(extraDinner)},total:chf(lodging+breakfast+other+cents(touristTax.amount)),lodgingDays:lodgingDays.map(x=>({date:x.date,amount:chf(x.amount)}))};
}
function unchangedReservationTariff(old,updated){
 if(!old||!old.priceSnapshot)return false;
 const fields=['room','arrival','departure','adults','children','meal','taxExemptAdults','taxExemptChildren','extraBreakfast','extraLunch','extraDinner','extraMealDays'];
 return fields.every(field=>{
  const numeric=['adults','children','taxExemptAdults','taxExemptChildren','extraBreakfast','extraLunch','extraDinner'].includes(field);const original=field==='adults'?(old.adults==null||old.adults===''?old.people||1:old.adults):field==='meal'?(old.meal||'Nur Logis'):old[field];
  return numeric?Number(original||0)===Number(updated[field]||0):String(original||'')===String(updated[field]||'');
 });
}
function mealPricesForm(hotel){return '<section class="meal-price-settings"><h2>Verpflegungspreise</h2><p>Alle Preise pro Person und Nacht, brutto in CHF. Zimmerpreise sind immer ohne Verpflegung. Frühstück wird bei Übernachtung separat ausgewiesen (3.8 %), zusätzliche Mahlzeiten 8.1 %.</p><div class="price-fields">'+[['breakfast','Frühstück'],['halfBoard','Halbpension inkl. Frühstück'],['fullBoard','Vollpension inkl. Frühstück']].map(x=>'<div><h3>'+x[1]+'</h3>'+priceInput(hotel[x[0]+'Adult']||0,'Erwachsene CHF',x[0]+'Adult')+priceInput(hotel[x[0]+'Child']||0,'Kinder CHF',x[0]+'Child')+'</div>').join('')+'</div><h3>Zusatzmahlzeiten pro Person</h3><div class="price-fields">'+[['extraBreakfastPrice','Zusatzfrühstück CHF'],['extraLunchPrice','Zusatzmittagessen CHF'],['extraDinnerPrice','Zusatzabendessen CHF']].map(([k,label])=>'<div><h3>'+label.replace(' CHF','')+'</h3>'+priceInput(hotel[k]||0,'Preis pro Person CHF',k)+'</div>').join('')+'</div></section>'}
function validateMealPrices(h){for(const k of ['extraBreakfastPrice','extraLunchPrice','extraDinnerPrice']){const n=Number(h[k]||0);if(!Number.isFinite(n)||n<0||n>10000)throw Error('Zusatzmahlzeitenpreis ungültig')}for(const prefix of ['breakfast','halfBoard','fullBoard'])for(const suffix of ['Adult','Child']){const n=Number(h[prefix+suffix]||0);if(!Number.isFinite(n)||n<0||n>10000)throw Error('Verpflegungspreis ungültig')}for(const suffix of ['Adult','Child'])if(Number(h['halfBoard'+suffix])<Number(h['breakfast'+suffix])||Number(h['fullBoard'+suffix])<Number(h['breakfast'+suffix]))throw Error('Halb- und Vollpension müssen mindestens das Frühstück decken')}

