const get=(k,id)=>db[k].find(x=>x.id===id)||{}, label=(k,x)=>k==='rooms'?x.number:k==='bookings'?(get('guests',x.guest).name||'Gast')+' · '+x.arrival:k==='invoices'?x.number:x.name||x.id;
const nights=b=>Math.round((Date.parse(b.departure)-Date.parse(b.arrival))/86400000), active=b=>!['Anfrage','Storniert','Ausgecheckt'].includes(b.status), overlap=(a,b)=>a.arrival<b.departure&&b.arrival<a.departure;
const credited=id=>(get('invoices',id).credits||[]).reduce((n,c)=>n+Math.round(Number(c.amount)*100),0)/100;
const paid=id=>chf(db.payments.filter(p=>p.invoice===id).reduce((s,p)=>s+cents(p.amount),0)-(get('invoices',id).refunds||[]).reduce((s,p)=>s+cents(p.amount),0));
function bindSvgAction(el,fn){if(!el)return;el.setAttribute('tabindex','0');el.setAttribute('role','button');const title=el.querySelector('title');if(title&&title.textContent.trim())el.setAttribute('aria-label',title.textContent.trim());el.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();fn()});el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '||e.key==='Spacebar'){e.preventDefault();e.stopPropagation();if(!e.repeat)fn()}})}
const ACTION_ICON_PATHS={edit:'<path d="M4 19l4-1 11-11-3-3L5 15z"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',go:'<path d="M5 12h14m-6-6 6 6-6 6"/>',print:'<path d="M6 9V3h12v6M6 18H4V9h16v9h-2M6 15h12v6H6z"/>',hotelSave:'<path d="M4 3h16v18H4zM8 3v7h8V3M8 21v-7h8v7"/>',invoiceNew:'<path d="M12 4v16M4 12h16"/>',invoiceCreate:'<path d="M4 3h16v18H4zM8 3v7h8V3"/>',backup:'<path d="M4 3h16v18H4zM8 3v7h8V3"/>',tab:'<path d="M5 12h14m-6-6 6 6-6 6"/>',qrData:'<path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM17 14v3h3v4"/>',creditNew:'<path d="M12 4v16M4 12h16"/>',delete:'<path d="M4 7h16M9 4h6M7 7l1 14h8l1-14"/>',reception:'<path d="M4 12h16M14 6l6 6-6 6"/>',invoicePayment:'<path d="M3 7h18v11H3zM3 10h18"/>',mealPrint:'<path d="M6 9V3h12v6M6 18H4V9h16v9h-2M6 15h12v6H6z"/>',reminder:'<path d="M3 6h18v12H3zM3 6l9 7 9-7"/>'};
function btn(t,a,id='',cl=''){t=t.replace(/^\+\s*/,'');const path=t==='Zurück'?'<path d="M19 12H5m6-6-6 6 6 6"/>':t==='Neu'?ACTION_ICON_PATHS.invoiceNew:t==='Übersicht'?'<path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/>':t==='Arbeitsbereich'?'<path d="M4 5h16M4 12h16M4 19h16"/>':ACTION_ICON_PATHS[a]||(/PDF|Drucken/.test(t)?ACTION_ICON_PATHS.print:/Speichern/.test(t)?ACTION_ICON_PATHS.hotelSave:/Schliessen|Abbrechen/.test(t)?ACTION_ICON_PATHS.close:/Neu|Erstellen|Reservation/.test(t)?ACTION_ICON_PATHS.invoiceNew:ACTION_ICON_PATHS.go);const icon='<svg class="action-svg" viewBox="0 0 24 24" focusable="false" aria-hidden="true">'+path+'</svg>';const label=/^[✎→←＋]$/.test(t)?(/✎/.test(t)?'Bearbeiten':t==='←'?'Zurück':t==='＋'?'Hinzufügen':'Öffnen'):t;return '<button type="button" aria-label="'+esc(label)+'" class="'+cl+'" data-action="'+a+'" data-id="'+esc(id)+'">'+icon+'<span>'+esc(label)+'</span></button>'}
function card(s){return '<section class="card">'+s+'</section>'}
function metric(t,v){return card('<div class="metric-content"><span class="metric-label">'+esc(t)+'</span> <strong class="metric-value">'+esc(v)+'</strong></div>')}
function entry(t,s,a,id){return '<div class="entry"><div><b>'+esc(t)+'</b><small>'+esc(s)+'</small></div>'+btn('✎',a,id)+'</div>'}
function previewMail(id){const t=get('templates',id);if(!t.id)throw Error('E-Mail-Vorlage nicht gefunden');const guest=db.guests[0]||{},booking=db.bookings[0]||{},invoice=db.invoices[0]||{},fields={hotel:db.hotel.name||'',hoteladresse:formattedAddress(db.hotel),gast:guest.name||'Gast',anreise:booking.arrival||'',abreise:booking.departure||'',zimmer:booking.room?get('rooms',booking.room).number||'':'',rechnungsnummer:invoice.number||'',betrag:invoice.id?money(invoice.total):''};const fill=v=>String(v||'').replace(/{{([a-z]+)}}/g,(all,k)=>fields[k]===undefined?all:fields[k]);const subject=fill(t.subject),body=fill(t.body);dialog('<h2>E-Mail-Vorschau</h2><p><strong>Vorlage:</strong> '+esc(t.name)+'</p><label>Betreff</label><input readonly id="mail-subject" value="'+esc(subject)+'"><label>Nachricht</label><textarea id="mail-body" rows="10">'+esc(body)+'</textarea><label>Empfänger (optional)</label><input type="email" id="mail-to" value="'+esc(guest.email||'')+'" placeholder="gast@example.ch"><p class="notice">Die Platzhalter verwenden vorhandene Beispieldaten. Vor dem Versand bitte prüfen.</p><div class="actions">'+btn('E-Mail vorbereiten','mailCompose',id,'primary')+btn('Schliessen','close')+'</div>')}
function navigate(p){page=p;tab='overview';query='';listPage=1;listFilters={};render()}

const HELP_SECTIONS=[["Erste Schritte","Trage unter Einstellungen zuerst Hotelname, Strasse, Hausnummer, PLZ, Ort, Land, IBAN und E-Mail ein. Diese Angaben werden später auf Dokumenten verwendet.","settings"],["Startseite und Suche","Die Startseite zeigt aktuelle Reservationen und wichtige Kennzahlen. Mit der Lupe kannst du nach Gästen, Buchungen und Nummern suchen.","dashboard"],["Gästeverwaltung","Lege Gäste mit Namen, Kontaktangaben, Geburtsdatum, getrennter Adresse und bei Bedarf mit Ausweisdokument an. Kontrolliere die Angaben vor dem Speichern.","guests"],["Zimmerkalender und Zimmer","Lege Zimmer und Preise an. Im Kalender siehst du die Belegung. Bei der Reservation wird eine Doppelbelegung geprüft.","calendar"],["Reservationen","Wähle Gast, Zimmer, Anreise und Abreise. Ergänze Personenzahl und Verpflegung. Anschliessend die Reservation speichern.","bookings"],["Check-in und Check-out","Öffne den Bereich und wähle die Reservation. Bestätige den passenden Statuswechsel. Nach dem Check-out kann eine Reinigungsaufgabe erstellt werden.","reception"],["Housekeeping und Gastronomie","Erfasse Reinigungsaufträge und markiere erledigte Aufgaben. Die Gastronomieansicht nutzt die Verpflegungsangaben aus Reservationen.","tasks"],["Kurtaxe / Gästetaxe","Öffne Einstellungen und aktiviere die Kurtaxe nur dann, wenn sie am Standort erhoben wird. Trage die gültigen Ansätze für Erwachsene und Kinder pro Nacht ein. Bei jeder Reservation gibst du an, wie viele Erwachsene oder Kinder laut Ortsreglement befreit sind. STAY Swiss berechnet daraus die Abgabe und zeigt sie separat auf der Rechnung. Prüfe Ausnahmen und MWST-Behandlung nach dem örtlichen Reglement.","settings"],["Rechnungen und Zahlungen","Rechnungen werden aus Reservationen erstellt. Prüfe Beträge und MWST. Zahlungen werden separat gebucht; Gutschriften und Mahnungen stehen je nach Rechnungsstatus zur Verfügung.","invoices"],["PDF und Druck","Öffne ein Dokument und wähle PDF / Drucken. Speichere ein PDF über den Android-Druckdialog. Die Schaltfläche Schliessen führt zurück. Noch nicht alle PDF-Mockups sind umgesetzt.",null],["E-Mail-Vorlagen","Du kannst Betreff und Nachricht ändern. Vorschau setzt vorhandene Daten in Platzhalter ein. E-Mail vorbereiten öffnet eine installierte Mail-App zum abschliessenden Versand.","templates"],["Datensicherung","Erstelle regelmässig eine JSON-Sicherung. Der Import ersetzt vorhandene Daten. Bewahre Sicherungen geschützt auf und kontrolliere sie vor dem Import.","backup"],["Datenschutz und Einschränkungen","App-Daten werden lokal gespeichert. Schütze das Gerät vor unbefugtem Zugriff. Die QR- und Finanzfunktionen sind derzeit nicht für den produktiven Zahlungsverkehr freigegeben.",null]];

