let documentDay=today(),documentReturnPage='documents',documentLast=null;
function htmlCell(v){return '<td>'+esc(v==null?'':v)+'</td>'}
function htmlTable(columns,rows){return '<div class="report-table-wrap"><table class="report-table"><thead><tr>'+columns.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(htmlCell).join('')+'</tr>').join('')+'</tbody></table></div>'}
function selectBookings(day,condition){return db.bookings.filter(b=>b.status!=='Storniert'&&condition(b,day))}
function reportMonthStats(year,month){const days=new Date(Date.UTC(year,month,0)).getUTCDate(),start=year+'-'+String(month).padStart(2,'0')+'-01',stop=month===12?(year+1)+'-01-01':year+'-'+String(month+1).padStart(2,'0')+'-01';const nights=db.bookings.filter(b=>!['Anfrage','Storniert'].includes(b.status)&&b.arrival<stop&&b.departure>start);let occupied=0;for(const room of db.rooms)for(let d=1;d<=days;d++){const date=year+'-'+String(month).padStart(2,'0')+'-'+String(d).padStart(2,'0');if(nights.some(b=>b.room===room.id&&b.arrival<=date&&date<b.departure))occupied++}const capacity=db.rooms.length*days;return {days,occupied,capacity,free:capacity-occupied,percent:capacity?Math.round(occupied*1000/capacity)/10:0}}
function mealDayCounts(b,day){const n=Math.max(0,Number(b.people)||0);if(['Anfrage','Storniert'].includes(b.status)||day<b.arrival||day>b.departure)return [0,0,0];const override=extraMealOverrides(b)[day];const extra=k=>override?override[['extraBreakfast','extraLunch','extraDinner'].indexOf(k)]:Math.max(0,Math.min(100,Math.floor(Number(b[k])||0)));return [ (['Frühstück','Halbpension','Vollpension'].includes(b.meal)&&b.arrival<day?n:0)+(b.arrival<day?extra('extraBreakfast'):0),(b.meal==='Vollpension'&&b.arrival<day&&day<b.departure?n:0)+(b.arrival<day&&day<b.departure?extra('extraLunch'):0),(['Halbpension','Vollpension'].includes(b.meal)&&day<b.departure?n:0)+(day<b.departure?extra('extraDinner'):0) ]}
function mealCounts(b){const n=Math.max(0,Number(b.people)||0);return [ ['Frühstück','Halbpension','Vollpension'].includes(b.meal)?n:0,b.meal==='Vollpension'?n:0,['Halbpension','Vollpension'].includes(b.meal)?n:0 ]}
function financePeriod(data,start,end){const within=x=>x.date>=start&&x.date<=end,sum=(items,key)=>items.reduce((n,x)=>n+cents(x[key]||0),0),invoices=data.invoices.filter(within),credits=data.invoices.flatMap(i=>i.credits||[]).filter(within),refunds=data.invoices.flatMap(i=>i.refunds||[]).filter(within),payments=data.payments.filter(within);const gross=sum(invoices,'total'),credit=sum(credits,'amount'),received=sum(payments,'amount'),refund=sum(refunds,'amount');const outstanding=data.invoices.filter(i=>i.date<=end).reduce((n,i)=>n+Math.max(0,cents(i.total)-sum((i.credits||[]).filter(c=>c.date<=end),'amount')-sum(data.payments.filter(p=>p.invoice===i.id&&p.date<=end),'amount')+sum((i.refunds||[]).filter(c=>c.date<=end),'amount')),0);return {gross,credit,received,refund,netSales:gross-credit,netPayments:received-refund,outstanding,count:invoices.length}}
function financeRows(q){return [['Rechnungsumsatz',q.gross],['Gutschriften',q.credit],['Umsatz nach Gutschriften',q.netSales],['Zahlungseingänge',q.received],['Rückerstattungen',q.refund],['Netto-Zahlungsfluss',q.netPayments],['Offene Forderungen am Stichtag',q.outstanding]].map(([k,v])=>[k,(v/100).toFixed(2)])}
function vatPeriod(data,start,end){const groups={},within=x=>x.date>=start&&x.date<=end;let passThrough=0;const add=(lines,sign)=>{for(const l of lines){if(l.taxTreatment==='pass_through')passThrough+=sign*cents(l.amount)}for(const t of invoiceTax(lines)){const k=t.rate,g=groups[k]||(groups[k]={rate:k,net:0,tax:0,gross:0});for(const f of ['net','tax','gross'])g[f]+=sign*cents(t[f])}};for(const i of data.invoices){if(within(i))add(i.lines||[],1);for(const c of i.credits||[])if(within(c))add([c],-1)}return {groups:Object.values(groups).sort((a,b)=>a.rate-b.rate),passThrough}}
function vatRange(day,period){const y=Number(day.slice(0,4)),m=Number(day.slice(5,7));if(period==='day')return [day,day];const first=period==='year'?1:period==='quarter'?Math.floor((m-1)/3)*3+1:m,last=period==='year'?12:period==='quarter'?first+2:m;return [y+'-'+String(first).padStart(2,'0')+'-01',y+'-'+String(last).padStart(2,'0')+'-'+new Date(Date.UTC(y,last,0)).getUTCDate()]}
function reportBuild(id,day,selectedId){const title=DOCUMENT_TYPES.find(x=>x.id===id);if(!title||!title.available)throw Error('Dieser PDF-Bericht ist noch nicht implementiert.');const bookings=selectBookings(day,()=>true);let columns=[],rows=[],summary='',notes='Datenstand '+day+' · Quelle: lokale STAY Swiss App';const asGuest=b=>get('guests',b.guest).name||'Nicht zugeordnet';const asRoom=b=>get('rooms',b.room).number||'–';
 switch(id){
 case 'fundgegenstande-protokoll':
 case 'gastewunsche':
 case 'wartungsliste':
 case 'schichtubergabe':{
 const key=({'fundgegenstande-protokoll':'lostItems','gastewunsche':'guestWishes','wartungsliste':'maintenance','schichtubergabe':'handover'})[id];
 columns=['Datum','Bezeichnung','Ort / Zuordnung','Notizen','Status'];
 rows=(db[key]||[]).filter(x=>x.date<=day).sort((a,b)=>b.date.localeCompare(a.date)).map(x=>[x.date,x.name,key==='maintenance'&&x.room?['Zimmer '+(get('rooms',x.room).number||x.room),x.location].filter(Boolean).join(' · '):key==='guestWishes'&&x.guest&&x.room?[(get('guests',x.guest).name||x.guest),'Zimmer '+(get('rooms',x.room).number||x.room)].join(' · '):x.location,x.details,x.status]);
 const records=(db[key]||[]).filter(x=>x.date<=day);if(key==='lostItems'){columns=['Nr.','Fundort','Gegenstand','Aufbewahrung','Status'];rows=records.map(x=>[x.foundNumber||'–',x.location,x.name,x.storageLocation||'–',x.status])}if(key==='maintenance'){columns=['Zimmer','Defekt','Priorität','Termin','Status'];rows=records.map(x=>[get('rooms',x.room).number||'–',x.name,x.priority||'–',x.dueDate||'–',x.status])}if(key==='guestWishes'){columns=['Zimmer','Wunsch','Termin','Abteilung','Status'];rows=records.map(x=>[get('rooms',x.room).number||'–',x.name,x.dueTime||'–',x.department||'–',x.status])}if(key==='handover'){columns=['Bereich','Aufgabe','Zuständig','Übergabezeit','Status'];rows=records.map(x=>[x.department||x.location,x.name,x.assignee||'–',x.handoverTime||'–',x.status])}summary=rows.length+' gespeicherte Einträge bis '+day;break}
 case 'checkin-checkout-tagesliste':{const a=bookings.filter(b=>b.arrival===day),d=bookings.filter(b=>b.departure===day);columns=['Ereignis','Zimmer','Gast','Personen','Status'];rows=a.map(b=>['Anreise',asRoom(b),asGuest(b),b.people,b.status]).concat(d.map(b=>['Abreise',asRoom(b),asGuest(b),b.people,b.status]));summary=a.length+' Anreisen · '+d.length+' Abreisen';break}
 case 'in-house-gasteliste':{const guests=bookings.filter(b=>b.arrival<=day&&day<b.departure&&b.status==='Eingecheckt');columns=['Gast','Zimmer','Anreise','Abreise','Personen'];rows=guests.map(b=>[asGuest(b),asRoom(b),b.arrival,b.departure,b.people]);summary=guests.length+' eingecheckte Reservationen';break}
 case 'gastemeldeformular':{const g=db.guests.find(x=>x.id===selectedId);if(!g)throw Error('Bitte einen Gast auswählen.');columns=['Angabe','Gastdaten'];rows=[['Name',g.name],['Wohnadresse',formattedAddress(g)],['Nationalität',g.nationality||'Nicht erfasst'],['Wohnsitzland',g.country||'–'],['Geburtsdatum',g.birthDate||'–'],['Ausweisdokument',g.documentType||'–'],['Dokumentnummer',g.documentNumber||'–'],['Gültig bis',g.documentExpiry||'–'],['Aufenthalt',(()=>{const b=db.bookings.filter(b=>b.guest===g.id&&!['Anfrage','Storniert'].includes(b.status)).sort((a,b)=>b.arrival.localeCompare(a.arrival)).find(b=>b.arrival<=day&&day<b.departure);return b?b.arrival+' – '+b.departure+' · Zimmer '+asRoom(b):'Kein Aufenthalt am Berichtsdatum'})()],['Begleitpersonen',(()=>{const b=db.bookings.find(b=>b.guest===g.id&&!['Anfrage','Storniert'].includes(b.status)&&b.arrival<=day&&day<b.departure);return b?(b.companions||((Math.max(0,Number(b.adults||b.people||1)-1))+' weitere Erwachsene · '+Number(b.children||0)+' Kinder')):'Nicht zugeordnet'})()],['Unterschrift','____________________________']];summary='Gästemeldeformular · '+g.name;notes='Bitte melderechtliche Anforderungen des Standortkantons prüfen; Unterschrift und Datenkontrolle sind erforderlich.';break}
 case 'freie-zimmer':{const occupied=new Set(bookings.filter(b=>active(b)&&b.arrival<=day&&day<b.departure).map(b=>b.room));const free=db.rooms.filter(x=>!occupied.has(x.id)&&x.status!=='Gesperrt');columns=['Zimmer','Kategorie','Reinigungsstatus','Preis CHF'];rows=free.map(x=>[x.number,x.category,x.status,Number(x.rate||0).toFixed(2)]);summary=free.length+' freie Zimmer';break}
 case 'zimmerstatusbericht':{const occupied=new Set(bookings.filter(b=>active(b)&&b.arrival<=day&&day<b.departure).map(b=>b.room));columns=['Zimmer','Kategorie','Belegung','Status'];rows=db.rooms.map(x=>[x.number,x.category,occupied.has(x.id)?'Belegt':'Frei',x.status]);summary=db.rooms.length+' Zimmer im Bestand';break}
 case 'zimmerreinigungsplan':{const work=db.tasks;columns=['Zimmer','Auftrag','Priorität','Personal','Status'];rows=work.map(t=>[get('rooms',t.room).number||'–',t.name,t.priority||'–',t.assignee||'–',t.status]);summary=work.length+' Aufträge · '+work.filter(t=>t.status==='Offen').length+' offen · '+work.filter(t=>t.status==='Kontrolle').length+' Kontrolle · '+work.filter(t=>t.status==='Erledigt').length+' erledigt';break}
 case 'offene-posten':{const invoices=db.invoices.map(x=>({x,remain:Math.max(0,Math.round((Number(x.total)-paid(x.id)-credited(x.id))*100)/100)})).filter(x=>x.remain>0);columns=['Rechnung','Gast','Fällig','Offen CHF'];rows=invoices.map(z=>[z.x.number,z.x.guest,z.x.dueDate||'–',z.remain.toFixed(2)]);summary='Offen gesamt: '+money(invoices.reduce((a,z)=>a+z.remain,0));break}
 case 'umsatz-nach-zahlungsarten':{const sums={};for(const [items,key] of [[db.payments,'received'],[db.invoices.flatMap(i=>i.refunds||[]),'refund']])for(const p of items.filter(p=>p.date===day)){const k=p.method||'Sonstige',g=sums[k]||(sums[k]={received:0,refund:0});g[key]+=cents(p.amount)}columns=['Zahlungsart','Eingänge CHF','Rückzahlungen CHF','Netto CHF'];rows=Object.entries(sums).map(([k,g])=>[k,...[g.received,g.refund,g.received-g.refund].map(v=>(v/100).toFixed(2))]);summary='Netto-Zahlungsfluss: '+money(Object.values(sums).reduce((n,g)=>n+g.received-g.refund,0)/100);notes='Zahlungsbewegungen am Berichtsdatum, kein Rechnungsumsatz.';break}
 case 'zahlungsquittung':{const p=db.payments.find(x=>x.id===selectedId);if(!p)throw Error('Bitte eine Zahlung auswählen.');const inv=get('invoices',p.invoice);columns=['Angabe','Wert'];rows=[['Rechnung',inv.number||'–'],['Gast',inv.guest||'–'],['Belegdatum',p.date],['Zahlungsart',p.method],['Betrag CHF',Number(p.amount).toFixed(2)]];summary='Erhalten: '+money(p.amount);notes='Zahlungsbeleg zu erfasster Buchung · Referenz '+(inv.number||'–');break}
 case 'tagesabschluss':{const q=financePeriod(db,day,day);columns=['Bereich','CHF'];rows=financeRows(q);summary='Tagesübersicht · '+q.count+' Rechnungen';notes='Rechnungs- und Zahlungsbewegungen getrennt; kein gesperrter buchhalterischer Abschluss.';break}
 case 'mwst-auswertung':{const [start,end]=vatRange(day,selectedId||'day'),q=vatPeriod(db,start,end);columns=['MWST-Satz','Netto CHF','MWST CHF','Brutto CHF'];rows=q.groups.map(t=>[t.rate+' %',...[t.net,t.tax,t.gross].map(v=>(v/100).toFixed(2))]);const totals=q.groups.reduce((n,t)=>[n[0]+t.net,n[1]+t.tax,n[2]+t.gross],[0,0,0]);rows.push(['Total',...totals.map(v=>(v/100).toFixed(2))],['Durchlaufende Posten','–','–',(q.passThrough/100).toFixed(2)]);summary=start+' bis '+end;notes='Auswertung nach Rechnungs- und Gutschriftdatum; keine offizielle MWST-Abrechnung. 0 % umfasst gespeicherte Nullsatzpositionen; steuerliche Einordnung und Vorsteuer separat prüfen.';break}
case 'gasteherkunft':{const countries={};db.guests.forEach(g=>{const country=String(g.country||'Unbekannt').trim()||'Unbekannt';countries[country]=(countries[country]||0)+1});columns=['Land (Code)','Anzahl Gäste'];rows=Object.keys(countries).sort().map(k=>[k,countries[k]]);summary=db.guests.length+' Gäste mit Länderangaben';notes='Auswertung der gespeicherten Wohnsitzländer, nicht zwingend der Staatsangehörigkeit.';break}
 case 'aufenthaltsplan':{const x=bookings.filter(b=>active(b)&&b.arrival<=day&&day<b.departure);columns=['Gast','Zimmer','Anreise','Abreise','Personen','Status'];rows=x.map(b=>[asGuest(b),asRoom(b),b.arrival,b.departure,b.people,b.status]);summary=x.length+' laufende Aufenthalte';break}
 case 'verpflegungsplan':{const x=bookings.filter(b=>!['Anfrage','Storniert'].includes(b.status)&&b.arrival<=day&&day<=b.departure);columns=['Zimmer','Gast','Verpflegung','Pers.','F','M','A'];rows=x.map(b=>[asRoom(b),asGuest(b),b.meal||'Nur Logis',Number(b.people||0),...mealDayCounts(b,day)]);const totals=x.reduce((n,b)=>mealDayCounts(b,day).map((v,i)=>v+n[i]),[0,0,0]);summary='Frühstück '+totals[0]+' · Mittag '+totals[1]+' · Abend '+totals[2];notes='Planwerte mit An- und Abreisetagen. Kein Konsumnachweis.';break}
 case 'wochenverpflegung':{const start=new Date(day+'T12:00:00Z');columns=['Datum','Frühstück','Mittag','Abend'];rows=Array.from({length:7},(_,i)=>{const date=new Date(start.getTime()+i*86400000).toISOString().slice(0,10);const x=bookings.filter(b=>!['Anfrage','Storniert'].includes(b.status)&&b.arrival<=date&&date<=b.departure);return [date,...x.reduce((n,b)=>mealDayCounts(b,date).map((v,i)=>v+n[i]),[0,0,0])]});const total=rows.reduce((n,r)=>n.map((v,i)=>v+r[i+1]),[0,0,0]);summary='Total: '+total[0]+' Frühstücke · '+total[1]+' Mittagessen · '+total[2]+' Abendessen';notes='Sieben Tage ab '+day+' · Planwerte mit An- und Abreisetagen, keine Verbrauchserfassung.';break}
 case 'wochenbelegungsplan':{const start=new Date(day+'T12:00:00Z');const days=Array.from({length:7},(_,i)=>new Date(start.getTime()+i*86400000).toISOString().slice(0,10));columns=['Zimmer'].concat(days.map(x=>x.slice(5)));rows=db.rooms.map(room=>[room.number].concat(days.map(date=>{const found=bookings.find(b=>active(b)&&b.room===room.id&&b.arrival<=date&&date<b.departure);return found?'Belegt':room.status==='Gesperrt'?'Gesperrt':'Frei'})));summary=db.rooms.length+' Zimmer · Sieben-Tage-Belegung ab '+day;break}
 case 'umsatz-nach-zimmerkategorien':{const sums={};for(const inv of db.invoices){const booking=get('bookings',inv.booking),cat=inv.roomCategory||get('rooms',booking.room).category||'Nicht zugeordnet',gross=inv.date===day?cents(inv.total):0,credit=(inv.credits||[]).filter(c=>c.date===day).reduce((n,c)=>n+cents(c.amount),0);if(!gross&&!credit)continue;const g=sums[cat]||(sums[cat]={gross:0,credit:0});g.gross+=gross;g.credit+=credit}columns=['Zimmerkategorie','Rechnungen CHF','Gutschriften CHF','Netto CHF'];rows=Object.keys(sums).sort().map(k=>[k,...[sums[k].gross,sums[k].credit,sums[k].gross-sums[k].credit].map(v=>(v/100).toFixed(2))]);summary='Umsatz nach Gutschriften: '+money(Object.values(sums).reduce((n,g)=>n+g.gross-g.credit,0)/100);notes='Zuordnung nach gespeicherter oder aktueller Zimmerkategorie; enthält weitere Rechnungspositionen. Kein reiner Logisumsatz.';break}
 case 'kassenbericht':{const c=db.cashDays.find(x=>x.date===day);if(!c)throw Error('Bitte zuerst Kassenbestand erfassen');const q=cashTotals(c,db);columns=['Zeit','Vorgang','Ein CHF','Aus CHF'];rows=[['–','Anfangsbestand',Number(c.opening).toFixed(2),'–'],...q.entries.map(e=>[e.time||'–',e.name,e.kind==='Ein'?Number(e.amount).toFixed(2):'–',e.kind==='Aus'?Number(e.amount).toFixed(2):'–'])];summary='Sollbestand '+money(q.expected/100)+' · Istbestand '+money(c.counted)+' · Differenz '+money(q.difference/100);notes='Kasse: '+c.name+' · Veränderbarer Tagesstand, kein gesperrter Abschluss.';break}
 case 'housekeeping-kontrollbericht':{columns=['Zimmer','Kontrolle','Mangel','Freigabe'];rows=db.tasks.map(t=>[get('rooms',t.room).number||'–',t.inspection||'Nicht geprüft',t.defect||'–',t.release||'Nein']);summary=db.tasks.filter(t=>t.release==='Ja').length+' freigegeben · '+db.tasks.filter(t=>t.release!=='Ja').length+' nicht freigegeben';notes='Aktueller Aufgabenbestand; keine historische Verlaufsauswertung.';break}
 case 'monatsbelegungsplan':{const year=Number(day.slice(0,4)),month=Number(day.slice(5,7)),m=reportMonthStats(year,month);const days=Array.from({length:m.days},(_,i)=>day.slice(0,7)+'-'+String(i+1).padStart(2,'0'));columns=['Zimmer','Kategorie','Belegte Nächte','Freie Nächte','Belegung %'];rows=db.rooms.map(room=>{const count=days.filter(date=>bookings.some(b=>!['Anfrage','Storniert'].includes(b.status)&&b.room===room.id&&b.arrival<=date&&date<b.departure)).length;return [room.number,room.category||'–',count,m.days-count,m.days?Math.round(1000*count/m.days)/10+' %':'0 %']});summary='Monat '+day.slice(0,7)+' · Belegte Zimmernächte '+m.occupied+' / '+m.capacity+' · '+m.percent+' %';notes='Monatliche Belegungsübersicht. Gesperrte Zimmer und Reinigung sind mangels historischer Statusdaten nicht zeitbezogen berücksichtigt.';break}
 case 'jahresbelegungsubersicht':{const year=Number(day.slice(0,4));columns=['Monat','Zimmernächte','Belegt','Frei','Auslastung'];const months=['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];rows=months.map((name,i)=>{const stats=reportMonthStats(year,i+1);return [name,stats.capacity,stats.occupied,stats.free,stats.percent+' %']});const total=rows.reduce((a,row)=>a+Number(row[1]),0),used=rows.reduce((a,row)=>a+Number(row[2]),0);summary=year+' · '+db.rooms.length+' Zimmer · Auslastung '+(total?Math.round(1000*used/total)/10:0)+' %';notes='Zimmernächte nach gespeicherten Reservationen, nicht nach historisch verfügbarem Zimmerbestand. Nicht als geprüfte Jahresabschlussstatistik verwenden.';break}
 case 'rechnung':{const inv=db.invoices.find(x=>x.id===selectedId);if(!inv)throw Error('Bitte eine Rechnung auswählen.');const taxes=invoiceTax(inv.lines||[]);columns=['Leistung','MWST %','Brutto CHF'];rows=(inv.lines||[]).map(l=>[l.name,l.vat||'0',Number(l.amount||0).toFixed(2)]);rows.push(['Rechnungsnummer',inv.number||'–',''],['Gast',inv.guest||'–',''],['Aufenthalt',(inv.arrival||'–')+' – '+(inv.departure||'–'),''],['Rechnungsdatum',inv.date||'–',''],['Fällig',inv.dueDate||'–',''],['Total CHF','',Number(inv.total||0).toFixed(2)],['Bezahlt CHF','',paid(inv.id).toFixed(2)],['Gutschriften CHF','',credited(inv.id).toFixed(2)],['Offen CHF','',Math.max(0,Number(inv.total||0)-paid(inv.id)-credited(inv.id)).toFixed(2)]);for(const t of taxes)rows.push(['MWST '+t.rate+' %',t.net.toFixed(2)+' netto',t.tax.toFixed(2)+' Steuer']);summary='Gastrechnung '+inv.number+' · '+money(inv.total);notes='Rechnungsbeleg aus gespeicherten Positionen; Zahlungsteil gemäss Swiss-QR-Standards nicht Bestandteil dieses Berichts.';break}
 case 'gutschrift':{const parts=String(selectedId||'').split(':');const inv=db.invoices.find(x=>x.id===parts[0]),credit=inv&&(inv.credits||[])[Number(parts[1])];if(!credit||!inv)throw Error('Bitte eine gespeicherte Gutschrift auswählen.');const rate=Number(credit.vat||0),gross=Number(credit.amount||0),net=gross/(1+rate/100);columns=['Angabe','Wert'];rows=[['Dokumentnummer',credit.number],['Rechnung',inv.number],['Empfänger',inv.guest||'–'],['Datum',credit.date],['Leistung',credit.name||'–'],['Begründung',credit.reason||'–'],['MWST-Satz',rate+' %'],['Netto CHF',net.toFixed(2)],['MWST CHF',(gross-net).toFixed(2)],['Gutschrift CHF',gross.toFixed(2)]];summary='Gutschrift '+credit.number+' · '+money(gross);notes='Beleg zu gespeicherter Rechnung. Rückerstattungen/Zahlungsflüsse sind separat zu prüfen.';break}
 case 'anreiseinformationen':{const b=db.bookings.find(x=>x.id===selectedId);if(!b)throw Error('Bitte eine Reservation auswählen.');const room=get('rooms',b.room);columns=['Angabe','Information'];rows=[['Gast',asGuest(b)],['Anreise',b.arrival+(db.hotel.checkInTime?' ab '+db.hotel.checkInTime:'')],['Abreise',b.departure+(db.hotel.checkOutTime?' bis '+db.hotel.checkOutTime:'')],['Zimmer',asRoom(b)+' · '+(room.category||'–')],['Personen',b.people],['Verpflegung',(b.meal||'–')+(b.meal&&b.meal!=='Nur Logis'&&db.hotel.breakfastHours?' · Frühstück '+db.hotel.breakfastHours:'')],['Parkplatz',db.hotel.parkingInfo||'Nicht hinterlegt'],['Rezeption',db.hotel.receptionHours||'Nicht hinterlegt'],['Hoteladresse',formattedAddress(db.hotel)],['Kontakt',[db.hotel.email,db.hotel.phone].filter(Boolean).join(' · ')||'–']];summary='Anreiseinformationen · '+asGuest(b);notes='Angaben gemäss gespeichertem Hotelprofil. Nicht hinterlegte Informationen bitte beim Hotel erfragen.';break}
 case 'ruckerstattungsbeleg':{const [invoiceId,index]=String(selectedId||'').split(':'),inv=db.invoices.find(x=>x.id===invoiceId),r=inv&&(inv.refunds||[])[Number(index)];if(!r)throw Error('Bitte eine gespeicherte Rückerstattung auswählen.');columns=['Angabe','Wert'];rows=[['Belegnummer',r.number],['Rechnung',inv.number],['Gast',inv.guest],['Auszahlungsdatum',r.date],['Zahlungsart',r.method],['Zahlungsnachweis',r.reference],['Begründung',r.reason],['Rückerstattung CHF',Number(r.amount).toFixed(2)]];summary='Rückerstattung '+r.number+' · '+money(r.amount);notes='Dokumentation einer manuell bestätigten Rückzahlung; keine automatische Banktransaktion.';break}
 case 'gruppenreservation':{const group=String(selectedId||'').trim();const members=db.bookings.filter(b=>group&&b.groupRef===group&&b.status!=='Storniert');if(!members.length)throw Error('Bitte eine Gruppenreferenz auswählen.');columns=['Zimmer','Gast','Anreise','Abreise','Erwachsene','Kinder','Status','CHF'];let total=0,missing=0;rows=members.map(b=>{const q=b.priceSnapshot,amount=q&&Number.isFinite(Number(q.total))?cents(q.total):null;if(amount===null)missing++;else total+=amount;return [asRoom(b),asGuest(b),b.arrival,b.departure,b.adults==null?b.people:b.adults,b.children||0,b.status,amount===null?'–':chf(amount).toFixed(2)]});rows.push(['Total bekannte Preise','','','','','','',chf(total).toFixed(2)]);summary='Gruppe '+group+' · '+members.length+' Reservationen';notes='Einzelreservationen mit gemeinsamer Referenz; stornierte Buchungen ausgeschlossen. '+missing+' Reservationen ohne gespeicherte Gesamtkalkulation. Keine Sammelrechnung.';break}
 case 'anzahlungsrechnung':{const b=db.bookings.find(x=>x.id===selectedId);if(!b||b.status==='Storniert'||!(Number(b.depositAmount)>0)||!b.depositDue)throw Error('Bitte eine gültige Anzahlungsforderung auswählen.');columns=['Angabe','Wert'];rows=[['Gast',asGuest(b)],['Zimmer',asRoom(b)],['Anreise',b.arrival],['Abreise',b.departure],['Fällig am',b.depositDue],['Angeforderte Anzahlung CHF',Number(b.depositAmount).toFixed(2)],['IBAN',db.hotel.iban||'–']];summary='Anzahlungsforderung · '+money(b.depositAmount);notes='Entwurf einer Zahlungsaufforderung, keine gebuchte Zahlung oder separate MWST-Rechnung. Zahlungseingänge werden erst über die reguläre Rechnung erfasst.';break}
 case 'reservationsanderung':{const b=db.bookings.find(x=>x.id===selectedId);if(!b)throw Error('Bitte eine Reservation auswählen.');columns=['Angabe','Aktueller Stand'];rows=[['Gast',asGuest(b)],['Zimmer',asRoom(b)],['Anreise',b.arrival],['Abreise',b.departure],['Erwachsene',b.adults==null?b.people:b.adults],['Kinder',b.children||0],['Verpflegung',b.meal||'–'],['Status',b.status]];if(b.priceSnapshot)rows.push(['Gesamt CHF',Number(b.priceSnapshot.total).toFixed(2)]);summary='Änderungsmitteilung · '+asGuest(b);const history=b.changeHistory||[],last=history[history.length-1];if(last){const labels={guest:'Gast',room:'Zimmer',arrival:'Anreise',departure:'Abreise',adults:'Erwachsene',children:'Kinder',meal:'Verpflegung',status:'Status',depositAmount:'Anzahlung CHF',depositDue:'Anzahlung fällig'};rows.push(['Letzte Änderung',last.date.slice(0,10)]);for(const c of last.changes){const display=v=>c.field==='room'?(get('rooms',v).number||v):c.field==='guest'?(get('guests',v).name||v):v;rows.push([labels[c.field]||c.field,display(c.before)+' → '+display(c.after)])}}notes=last?'Letzte gespeicherte Änderung im Reservationseditor; Versand nicht nachgewiesen.':'Keine frühere Änderung im Reservationseditor dokumentiert.';break}
 case 'qr-rechnung':{const inv=db.invoices.find(x=>x.id===selectedId);if(!inv)throw Error('Bitte eine Rechnung auswählen.');qrPaymentData(inv.id);columns=['Angabe','Wert'];rows=[['Rechnung',inv.number],['Empfänger',(inv.issuer||db.hotel).name],['IBAN',(inv.issuer||db.hotel).iban],['Offen CHF',Math.max(0,Number(inv.total)-paid(inv.id)-credited(inv.id)).toFixed(2)]];summary='QR-Zahlteil · TESTENTWURF';notes='Nicht für den Zahlungsverkehr freigegeben.';break}
 case 'reservationsofferte':{const b=db.bookings.find(x=>x.id===selectedId);if(!b)throw Error('Bitte eine Reservation auswählen.');const room=get('rooms',b.room),q=b.priceSnapshot||null,rate=Number(b.rate==null?room.rate:b.rate),count=nights(b);if(!Number.isFinite(rate)||rate<0||!Number.isInteger(count)||count<=0)throw Error('Reservation oder Zimmerpreis ungültig');columns=['Angabe','Wert'];rows=[['Gast',asGuest(b)],['Zimmer',asRoom(b)],['Anreise',b.arrival],['Abreise',b.departure],['Nächte',count],['Erwachsene',b.adults==null?b.people:b.adults],['Kinder',b.children||0],['Gebuchte Verpflegung',b.meal||'–']];if(q){rows.push(['Logis inkl. MWST CHF',Number(q.lodging).toFixed(2)],['Frühstück inkl. MWST CHF',Number(q.breakfast).toFixed(2)],['Zusätzliche Mahlzeiten inkl. MWST CHF',Number(q.other).toFixed(2)],['Kurtaxe / Gästetaxe CHF',Number(q.touristTax||0).toFixed(2)],['Total CHF',Number(q.total).toFixed(2)]);}else rows.push(['Historischer Logis-Basispreis CHF',(rate*count).toFixed(2)]);rows.push(['Offertennummer',b.offerNumber||'Nicht vergeben'],['Gültig bis',b.offerValidUntil||'Nicht festgelegt'],['Anzahlung angefordert CHF',Number(b.depositAmount||0).toFixed(2)],['Restbetrag nach Anzahlung CHF',Math.max(0,(q?q.total:rate*count)-Number(b.depositAmount||0)).toFixed(2)]);summary='Unverbindlicher Angebotsentwurf · '+money(q?q.total:rate*count);notes='Unverbindlicher Entwurf auf Basis der gespeicherten Reservation. Konfigurierte Kurtaxe ist separat enthalten; weitere Leistungen und Anzahlungen separat prüfen. Anzahlung ist eine Forderung, kein bestätigter Zahlungseingang.';break}
 case 'stornierungsbestatigung':{const b=db.bookings.find(x=>x.id===selectedId);if(!b||b.status!=='Storniert')throw Error('Bitte eine stornierte Reservation auswählen.');columns=['Angabe','Wert'];rows=[['Gast',asGuest(b)],['Zimmer',asRoom(b)],['Anreise',b.arrival],['Abreise',b.departure],['Status','Storniert'],['Storniert am',b.cancelledAt||'Nicht dokumentiert'],['Begründung',b.cancellationReason||'Nicht dokumentiert'],['Stornogebühr CHF',Number(b.cancellationFee||0).toFixed(2)]];summary='Stornierungsübersicht · '+asGuest(b);notes='Gespeicherte Stornierungsangaben. Gebühren sind nicht automatisch fakturiert; Rückerstattungen separat erfassen.';break}
 case 'zahlungserinnerung':{const inv=db.invoices.find(x=>x.id===String(selectedId).split(':')[0]);if(!inv)throw Error('Bitte eine Rechnung auswählen.');const remaining=Math.round((Number(inv.total||0)-paid(inv.id)-credited(inv.id))*100)/100;if(remaining<=0)throw Error('Diese Rechnung hat keinen offenen Betrag.');columns=['Angabe','Wert'];rows=[['Rechnung',inv.number],['Empfänger',inv.guest||'–'],['Rechnungsdatum',inv.date||'–'],['Fälligkeitsdatum',inv.dueDate||'–'],['Betrag CHF',Number(inv.total||0).toFixed(2)],['Bezahlt CHF',paid(inv.id).toFixed(2)],['Offen CHF',remaining.toFixed(2)],['IBAN',(inv.issuer||db.hotel).iban||'–']];if(inv.paymentNotice)rows.push(['Dokumentnummer',inv.paymentNotice.number],['Neue Zahlungsfrist',inv.paymentNotice.dueDate],['Nachricht',inv.paymentNotice.message],['Kontakt',inv.paymentNotice.contact]);summary='Zahlungserinnerung · '+money(remaining);notes='ENTWURF – noch nicht versendet. Vor dem Versand Zahlungseingänge, Fälligkeit und Empfänger prüfen.';break}
 case 'jahresabschluss':
 case 'auswertung':{
 const annual=id==='jahresabschluss',period=day.slice(0,annual?4:7);
 const months=annual?Array.from({length:12},(_,i)=>period+'-'+String(i+1).padStart(2,'0')):[period];
 columns=['Zeitraum','Rechnungen CHF','Gutschriften CHF','Netto-Zahlungen CHF','Saldo CHF'];
 let totals=[0,0,0];
 for(const month of months){
 const inv=db.invoices.filter(x=>String(x.date||'').slice(0,7)===month);
 const gross=inv.reduce((n,x)=>n+cents(x.total||0),0);
 const credits=db.invoices.reduce((n,x)=>n+(x.credits||[]).filter(c=>String(c.date||'').slice(0,7)===month).reduce((a,c)=>a+cents(c.amount||0),0),0);
 const received=db.payments.filter(x=>String(x.date||'').slice(0,7)===month).reduce((n,x)=>n+cents(x.amount||0),0)-db.invoices.flatMap(x=>x.refunds||[]).filter(x=>String(x.date||'').slice(0,7)===month).reduce((n,x)=>n+cents(x.amount||0),0);
 totals=totals.map((v,i)=>v+[gross,credits,received][i]);
 rows.push([month,...[gross,credits,received,gross-credits-received].map(v=>chf(v).toFixed(2))]);
 }
 rows.push(['Total',...totals.concat(totals[0]-totals[1]-totals[2]).map(v=>chf(v).toFixed(2))]);
 if(annual){const q=financePeriod(db,period+'-01-01',period+'-12-31');rows.push(['Offene Forderungen am Jahresende','','','', (q.outstanding/100).toFixed(2)])}summary=(annual?'Jahresübersicht ':'Betriebsübersicht ')+period;
 notes='Entwurf: Saldo ist die Differenz der Periodenbewegungen, kein Debitorenbestand oder buchhalterischer Abschluss. Zahlungen abzüglich Rückzahlungen und Gutschriften werden nach ihrem eigenen Datum zugeordnet.';
 break}
 case 'monatsabschluss':{const month=day.slice(0,7),end=month+'-'+String(new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5)),0)).getUTCDate()).padStart(2,'0'),q=financePeriod(db,month+'-01',end);columns=['Bereich','CHF'];rows=financeRows(q);summary='Monatsübersicht '+month+' · '+q.count+' Rechnungen';notes='Entwurf; offene Forderungen zum Monatsende nach gespeicherten Belegdaten, kein geprüfter Abschluss.';break}
 case 'erste-mahnung':
 case 'zweite-mahnung':
 case 'letzte-mahnung':{const parts=String(selectedId||'').split(':'),inv=db.invoices.find(x=>x.id===parts[0]),entry=inv&&(inv.reminders||[])[Number(parts[1])];if(!inv||!entry)throw Error('Bitte eine gespeicherte Mahnung auswählen.');const level=Number(entry.level);if(id==='erste-mahnung'&&level!==1||id==='zweite-mahnung'&&level!==2||id==='letzte-mahnung'&&level<3)throw Error('Mahnstufe entspricht nicht dem Dokumenttyp.');columns=['Angabe','Wert'];rows=[['Mahnstufe',level],['Rechnung',inv.number||'–'],['Empfänger',inv.guest||'–'],['Mahndatum',entry.date||'–'],['Ursprünglich fällig',inv.dueDate||'–'],['Mahnstand CHF',Number(entry.amount||0).toFixed(2)],['Aktuell offen CHF',Math.max(0,Number(inv.total||0)-paid(inv.id)-credited(inv.id)).toFixed(2)],['IBAN',(inv.issuer||db.hotel).iban||'–']];summary=(level===1?'Erste Mahnung':level===2?'Zweite Mahnung':'Weitere Mahnung')+' · '+(inv.number||'–');notes='Gespeicherter Mahnstand. Versand und Zustellung sind nicht nachgewiesen. Vor erneuter Verwendung den aktuellen Zahlungsstand prüfen.';break}
  case 'buchungsbestaetigung':{const b=db.bookings.find(x=>x.id===selectedId);if(!b)throw Error('Bitte eine Reservation auswählen.');columns=['Angabe','Reservation'];rows=[['Gast',asGuest(b)],['Zimmer',asRoom(b)+' · '+(get('rooms',b.room).category||'')],['Anreise',b.arrival],['Abreise',b.departure],['Erwachsene',b.adults==null?b.people:b.adults],['Kinder',b.children||0],['Verpflegung',b.meal||'–'],['Status',b.status]];if(b.priceSnapshot){const q=b.priceSnapshot;rows.push(['Übernachtung inkl. MWST (3.8 %) CHF',Number(q.lodging).toFixed(2)],['Frühstück inkl. MWST (3.8 %) CHF',Number(q.breakfast).toFixed(2)],['Weitere Mahlzeiten inkl. MWST (8.1 %) CHF',Number(q.other).toFixed(2)],['Kurtaxe / Gästetaxe CHF',Number(q.touristTax||0).toFixed(2)],['Gesamtbetrag CHF',Number(q.total).toFixed(2)]);}else rows.push(['Bisheriger Zimmerpreis pro Nacht CHF',Number(b.rate==null?get('rooms',b.room).rate:b.rate).toFixed(2)]);summary='Reservationsbestätigung · '+asGuest(b);notes='Die gespeicherte Kalkulation inklusive allfälliger Kurtaxe bleibt bei späteren Tarifänderungen erhalten. Lokale Kurtaxenregeln und weitere Leistungen sind separat zu prüfen.';break}
 }
 return {id,name:title.name,day,columns,rows,summary,notes};
}
let documentSection='Rezeption';
function documentsPage(){const groups=['Rezeption','Reservationen','Gäste','Zimmer','Housekeeping','Gastronomie','Finanzen'];const section=groups.includes(documentSection)?documentSection:groups[0];const items=DOCUMENT_TYPES.filter(x=>x.section===section);return '<section class="info-intro"><span class="info-kicker">STAY Swiss · Dokumente</span><h2>PDF-Berichtszentrum</h2><div class="actions">'+btn('Datum ändern','documentPickDate')+'</div><p>Gewähltes Datum: <strong>'+esc(documentDay)+'</strong> · '+DOCUMENT_TYPES.length+' Dokumenttypen</p></section><div class="document-tabs" role="group" aria-label="Berichtsbereiche">'+groups.map(g=>'<button type="button" data-action="documentSection" data-id="'+esc(g)+'" aria-pressed="'+(g===section)+'" class="'+(g===section?'active':'')+'">'+esc(g)+' <span>'+DOCUMENT_TYPES.filter(x=>x.section===g).length+'</span></button>').join('')+'</div><section class="report-group"><h2>'+esc(section)+'</h2><div class="document-grid">'+items.map(x=>'<div class="document-choice"><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.description)+'</small></div><span class="document-status '+(x.available?'ready':'pending')+'">'+(x.available?'Verfügbar':'Noch offen')+'</span>'+(x.available?btn('Vorschau','documentPreview',x.id):'')+'</div>').join('')+'</div></section>'}

function reservationLetter(doc,id){const b=get('bookings',id),g=get('guests',b.guest),r=get('rooms',b.room),q=b.priceSnapshot,offer=doc.id==='reservationsofferte',issuer=db.hotel,rows=q?[['Übernachtung',q.nights,Number(q.lodging/q.nights).toFixed(2),Number(q.lodging).toFixed(2)],...['breakfast','other','touristTax'].filter(k=>Number(q[k])>0).map(k=>[({breakfast:'Frühstück',other:'Weitere Mahlzeiten',touristTax:'Kurtaxe'})[k],1,Number(q[k]).toFixed(2),Number(q[k]).toFixed(2)])]:[];return '<article class="report-a4 invoice-report"><div class="report-topline"></div><header class="invoice-letterhead"><div class="invoice-brand"><img class="app-brand-logo" src="app-logo.svg" alt="STAY Swiss"><div><strong>STAY Swiss</strong><small>HOTEL MANAGEMENT</small></div></div><div class="invoice-issuer"><strong>'+esc(issuer.name)+'</strong><div>'+esc(formattedAddress(issuer))+'</div><div>'+esc(issuer.email||'')+'</div></div></header><h1>'+esc(doc.name)+'</h1><dl class="invoice-meta"><dt>Reservation</dt><dd>'+esc(b.number||b.id)+'</dd><dt>Gast</dt><dd>'+esc(g.name||'–')+'</dd><dt>Anreise / Abreise</dt><dd>'+esc(b.arrival+' – '+b.departure)+'</dd>'+(offer?'<dt>Gültig bis</dt><dd>Nicht festgelegt</dd>':'')+'</dl>'+ (offer?htmlTable(['Leistung','Anzahl','Preis CHF','Total CHF'],rows):htmlTable(['Zimmer','Personen','Verpflegung','Preis CHF'],[[r.number+' · '+r.category,(b.adults||b.people)+' Erw. / '+(b.children||0)+' Kinder',b.meal||'–',q?Number(q.total).toFixed(2):'–']]))+'<div class="invoice-bottom"><div><h3>Hinweise</h3><p>'+esc(doc.notes)+'</p></div><div class="invoice-totals">'+(q?'<div><span>Gesamt</span><strong>'+money(q.total)+'</strong></div><div><span>Vorgesehene Anzahlung</span><strong>'+money(b.depositAmount||0)+'</strong></div>':'<p>Keine gespeicherte Gesamtkalkulation</p>')+'</div></div><footer class="report-footer">'+esc(issuer.name)+' · STAY Swiss</footer></article>'}
function creditLetter(doc,selectedId){const [id,index]=String(selectedId).split(':'),inv=get('invoices',id),c=inv.credits[Number(index)],issuer=inv.issuer||db.hotel,t=invoiceTax([c])[0];return '<article class="report-a4 payment-letter"><div class="report-topline"></div><header class="invoice-letterhead"><div class="invoice-brand"><img class="app-brand-logo" src="app-logo.svg" alt="STAY Swiss"><div><strong>STAY Swiss</strong><small>HOTEL MANAGEMENT</small></div></div><div class="invoice-issuer"><strong>'+esc(issuer.name)+'</strong><div>'+esc(issuer.address||formattedAddress(issuer))+'</div><div>'+esc(issuer.email||'')+'</div></div></header><h1>Gutschrift</h1><div class="letter-recipient"><div><small>Empfänger</small><strong>'+esc(inv.guest)+'</strong><p>'+esc(inv.guestAddress||'–')+'</p></div><div><p>Dokument: '+esc(c.number)+'</p><p>Referenz: '+esc(inv.number)+'</p><p>Erstellt: '+esc(c.date)+'</p></div></div><div class="letter-amount"><div><small>Gutschriftbetrag</small><strong>'+money(c.amount)+'</strong></div><div><small>Belegdatum</small><strong>'+esc(c.date)+'</strong></div></div>'+htmlTable(['Referenz / Beschreibung','CHF'],[[inv.number+' · '+c.name,Number(c.amount).toFixed(2)]])+'<h3>Informationen</h3><p>'+esc(c.reason)+'</p><p>'+(t?'Netto '+money(t.net)+' · MWST '+t.rate+' %: '+money(t.tax):'Separat ausgewiesene Abgabe · keine MWST berechnet')+'</p><h3>Kontakt bei Rückfragen</h3><p>'+esc(issuer.email||'–')+'</p><footer class="report-footer">'+esc(issuer.name)+' · STAY Swiss</footer></article>'}
function paymentLetter(doc,selectedId){const deposit=doc.id==='anzahlungsrechnung',reminder=['erste-mahnung','zweite-mahnung','letzte-mahnung'].includes(doc.id),inv=deposit?null:get('invoices',String(selectedId).split(':')[0]),b=deposit?get('bookings',selectedId):null,g=deposit?get('guests',b.guest):null,entry=reminder?(inv.reminders||[])[Number(String(selectedId).split(':')[1])]:doc.id==='zahlungserinnerung'?inv.paymentNotice:null,issuer=inv?(inv.issuer||db.hotel):db.hotel,amount=deposit?Number(b.depositAmount):entry?Number(entry.amount):Math.max(0,Number(inv.total)-paid(inv.id)-credited(inv.id)),due=deposit?b.depositDue:entry?(entry.dueDate||'Nicht festgelegt'):inv.dueDate,reference=deposit?(b.number||b.id):inv.number,recipient=deposit?g.name:inv.guest,address=deposit?formattedAddress(g):inv.guestAddress,date=entry?entry.date:doc.day;return '<article class="report-a4 payment-letter"><div class="report-topline"></div><header class="invoice-letterhead"><div class="invoice-brand"><img class="app-brand-logo" src="app-logo.svg" alt="STAY Swiss"><div><strong>STAY Swiss</strong><small>HOTEL MANAGEMENT</small></div></div><div class="invoice-issuer"><strong>'+esc(issuer.name)+'</strong><div>'+esc(issuer.address||formattedAddress(issuer))+'</div><div>'+esc(issuer.email||'')+'</div></div></header><h1>'+esc(doc.name)+'</h1><div class="letter-recipient"><div><small>Empfänger</small><strong>'+esc(recipient||'–')+'</strong><p>'+esc(address||'–')+'</p></div><div>'+(entry?'<p>Dokument: '+esc(entry.number||'Nicht vergeben')+'</p>':'')+'<p>Referenz: '+esc(reference)+'</p><p>Erstellt: '+esc(date)+'</p></div></div><div class="letter-amount"><div><small>'+ (deposit?'Betrag':'Offener Betrag / dokumentierter Stand')+'</small><strong>'+money(amount)+'</strong></div><div><small>Zahlungsfrist</small><strong>'+esc(due||'–')+'</strong></div></div>'+htmlTable(['Referenz / Beschreibung','CHF'],[[reference+' · '+doc.name,amount.toFixed(2)],...(reminder&&entry&&Number(entry.fee)>0?[['Mahngebühr (separat, nicht verbucht)',Number(entry.fee).toFixed(2)],['Zahlungsbetrag inkl. Gebühr',(amount+Number(entry.fee)).toFixed(2)]]:[])])+'<h3>Informationen</h3><p>'+esc(entry&&entry.message?entry.message:doc.notes)+'</p>'+(deposit?'<p>Aufenthalt: '+esc(b.arrival)+' – '+esc(b.departure)+'</p>':'<p>Aktuell offen: '+money(Math.max(0,Number(inv.total)-paid(inv.id)-credited(inv.id)))+'</p>')+(entry?'<h3>Kontakt bei Rückfragen</h3><p>'+esc(entry.contact||issuer.email||'–')+'</p><p>Bitte geben Sie die Dokumentenreferenz an.</p>':'')+'<p>IBAN: '+esc(issuer.iban||'–')+'</p><footer class="report-footer">'+esc(issuer.name)+' · STAY Swiss</footer></article>'}
function annualOccupancyReport(doc){const values=doc.rows.map(r=>Math.max(0,Math.min(100,parseFloat(r[4])||0))),avg=doc.rows.reduce((n,r)=>n+Number(r[1]),0)?100*doc.rows.reduce((n,r)=>n+Number(r[2]),0)/doc.rows.reduce((n,r)=>n+Number(r[1]),0):0,best=Math.max(...values),months=['Jan','Feb','Mär','Apr','Mai','Jun','Jul','Aug','Sep','Okt','Nov','Dez'];const t=(x,y,v,size=10,weight=400,anchor='start')=>'<text x="'+x+'" y="'+y+'" font-family="Arial,sans-serif" font-size="'+size+'" font-weight="'+weight+'" fill="#243b53" text-anchor="'+anchor+'">'+esc(v)+'</text>';const rect=(x,y,w,h,fill,rx=0)=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" fill="'+fill+'" rx="'+rx+'"/>';return '<article class="report-a4 annual-occupancy-report"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 842 595" width="842" height="595" role="img" aria-label="Jahresbelegungsübersicht">'+rect(0,0,842,595,'#fff')+rect(0,0,842,8,'#284a6b')+'<image x="32" y="28" width="42" height="42" href="app-logo.svg"/>'+t(88,47,'STAY Swiss',21,700)+t(88,64,'HOTEL MANAGEMENT',9,700)+t(810,43,db.hotel.name||'',14,700,'end')+t(810,60,formattedAddress(db.hotel),10,400,'end')+rect(32,88,778,1,'#dce5ee')+t(32,124,doc.name,24,700)+t(32,150,'Januar–Dezember '+doc.day.slice(0,4)+' · '+db.rooms.length+' Zimmer',12)+rect(32,170,778,54,'#edf4fa',8)+t(45,192,'Jahresauslastung',11,700)+t(45,213,avg.toFixed(1)+' %',18,700)+t(440,192,'Stärkster Monat',11,700)+t(440,213,best?doc.rows[values.indexOf(best)][0]+' · '+best+' %':'–',18,700)+[0,25,50,75,100].map(p=>rect(80,450-p*1.92,720,1,'#dce5ee')+t(70,454-p*1.92,p+' %',10,400,'end')).join('')+values.map((v,i)=>rect(90+i*59,450-v*1.92,36,v*1.92,'#83b0d9',4)+t(108+i*59,440-v*1.92,v+' %',10,700,'middle')+t(108+i*59,470,months[i],10,400,'middle')).join('')+t(32,510,'Berechnet aus gespeicherten Reservationen und aktuellem Zimmerbestand.',10)+rect(32,540,778,1,'#dce5ee')+t(32,560,'STAY Swiss · '+doc.day,10)+t(810,560,'Seite 1 / 1',10,400,'end')+'</svg></article>'}
function cashTotals(c,data){const entries=[...data.payments.filter(p=>p.date===c.date&&p.method==='Bar').map(p=>({kind:'Ein',amount:p.amount,name:'Barzahlung'})),...data.invoices.flatMap(i=>i.refunds||[]).filter(p=>p.date===c.date&&p.method==='Bar').map(p=>({kind:'Aus',amount:p.amount,name:'Barrückzahlung'})),...c.entries];const expected=cents(c.opening)+entries.reduce((n,e)=>n+(e.kind==='Ein'?1:-1)*cents(e.amount),0);return {entries,expected,difference:cents(c.counted)-expected}}
function cashEditor(){const day=documentDay,c=db.cashDays.find(x=>x.date===day)||{id:uid(),date:day,name:'Rezeption',opening:0,counted:0,entries:[]};dialog('<h2>Kassenbuch · '+esc(day)+'</h2><form id="cash-form" class="compact-editor columns-2"><div class="editor-fields">'+[['name','Kasse','text'],['opening','Anfangsbestand CHF','number'],['counted','Istbestand CHF','number']].map(([k,l,t])=>'<div class="editor-field"><label>'+l+'</label><input name="'+k+'" type="'+t+'" '+(t==='number'?'min="0" step="0.01"':'')+' required value="'+esc(c[k])+'"></div>').join('')+'</div><p>Zusätzliche Bargeldbewegung (optional)</p><label>Art</label><select name="kind"><option>Ein</option><option>Aus</option></select><label>Betrag CHF</label><input name="amount" type="number" min="0.01" step="0.01"><label>Bezeichnung</label><input name="description"><label>Uhrzeit</label><input name="time" type="time"><p>'+esc(c.entries.map(e=>e.kind+' · '+e.name+' · '+money(e.amount)).join(' | '))+'</p><div class="actions">'+btn('Abbrechen','close')+'<button type="submit" class="primary">Speichern und PDF öffnen</button></div></form>');$('cash-form').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target).entries()),n=Object.assign({},c,{name:f.name,opening:Number(f.opening),counted:Number(f.counted),entries:c.entries.slice()});if(![n.opening,n.counted].every(v=>Number.isFinite(v)&&v>=0))throw Error('Ungültiger Bestand');if(f.amount){if(!f.description.trim()||!Number.isFinite(Number(f.amount))||Number(f.amount)<=0)throw Error('Betrag und Bezeichnung erforderlich');n.entries.push({kind:f.kind,amount:Number(f.amount),name:f.description,time:f.time})}atomicChange(()=>{db.cashDays=db.cashDays.filter(x=>x.date!==day).concat(n)},'Kassenbuch gespeichert '+day);close();documentPreview('kassenbericht','cash')}catch(err){alert(err.message)}}}
function paymentNoticeEditor(id){const inv=get('invoices',id),amount=Math.max(0,Number(inv.total)-paid(id)-credited(id));if(!inv.id||amount<=0){alert('Keine offene Forderung vorhanden.');return}const old=inv.paymentNotice||{},due=reminderDue('notice');dialog('<h2>Zahlungserinnerung</h2><form id="notice-form" class="compact-editor columns-2"><div class="editor-fields"><div class="editor-field"><label>Rechnung</label><input readonly value="'+esc(inv.number)+'"></div><div class="editor-field"><label>Offen</label><input readonly value="'+esc(money(amount))+'"></div><div class="editor-field"><label>Zahlungsfrist</label><input type="date" name="dueDate" min="'+today()+'" required value="'+esc(old.dueDate>=today()?old.dueDate:due)+'"></div><div class="editor-field"><label>Kontakt</label><input name="contact" value="'+esc(old.contact||db.hotel.reminderContact||db.hotel.email||'')+'"></div><div class="editor-field full-field"><label>Nachricht</label><textarea name="message" required>'+esc(old.message||db.hotel.noticeText)+'</textarea></div></div><div class="actions">'+btn('Abbrechen','close')+'<button type="submit" class="primary">Speichern und PDF öffnen</button></div></form>');$('notice-form').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target).entries());if(!f.message.trim()||f.dueDate<today())throw Error('Nachricht und gültige Zahlungsfrist erforderlich');atomicChange(()=>{inv.paymentNotice={number:old.number||'ZE-'+inv.number,date:today(),dueDate:f.dueDate,contact:f.contact,message:f.message,amount}},'Zahlungserinnerung gespeichert '+inv.number);close();documentPreview('zahlungserinnerung',id+':notice')}catch(err){alert(err.message)}}}
function documentPreview(id,selectedId){if(id==='zahlungserinnerung'&&selectedId&&!String(selectedId).includes(':')){paymentNoticeEditor(selectedId);return}if(id==='mwst-auswertung'&&!selectedId){dialog('<h2>MWST-Auswertung</h2><form id="vat-period"><label>Abrechnungsperiode</label><select name="period"><option value="day">Tag</option><option value="month">Monat</option><option value="quarter">Quartal</option><option value="year">Jahr</option></select><div class="actions">'+btn('Abbrechen','close')+'<button type="submit" class="primary">PDF öffnen</button></div></form>');$('vat-period').onsubmit=e=>{e.preventDefault();const p=e.target.elements.period.value;close();documentPreview(id,p)};return}if(id==='kassenbericht'&&!selectedId){cashEditor();return}if(id==='verpflegungsplan'){mealPrint(mealPlan(documentDay),documentDay);return}if(id==='ruckerstattungsbeleg'&&!selectedId){const records=db.invoices.flatMap(inv=>(inv.refunds||[]).map((r,i)=>({id:inv.id+':'+i,name:r.number+' · '+money(r.amount)})));if(!records.length){dialog('<h2>Rückerstattungsbeleg</h2><p>Keine Rückzahlungen erfasst.</p>'+btn('Schliessen','close'));return}dialog('<h2>Rückerstattungsbeleg</h2><form id="refund-select"><select name="record">'+records.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+'</option>').join('')+'</select><button type="submit">PDF-Vorschau öffnen</button>'+btn('Abbrechen','close')+'</form>');$('refund-select').onsubmit=e=>{e.preventDefault();const v=e.target.elements.record.value;close();documentPreview(id,v)};return}if(id==='gruppenreservation'&&!selectedId){const groups=[...new Set(db.bookings.filter(b=>b.groupRef&&b.status!=='Storniert').map(b=>b.groupRef))].sort();if(!groups.length){dialog('<h2>Gruppenreservation</h2><p>Keine Gruppenreferenzen vorhanden. Tragen Sie dieselbe Gruppenreferenz in den zugehörigen Reservationen ein.</p>'+btn('Schliessen','close'));return}dialog('<h2>Gruppenreservation</h2><form id="group-report-form"><label>Gruppenreferenz</label><select name="group" required>'+groups.map(g=>'<option value="'+esc(g)+'">'+esc(g)+'</option>').join('')+'</select><div class="actions"><button type="submit">PDF-Vorschau öffnen</button>'+btn('Abbrechen','close')+'</div></form>');$('group-report-form').onsubmit=e=>{e.preventDefault();const group=e.target.elements.group.value;close();documentPreview(id,group)};return}if(!selectedId&&['gastemeldeformular','buchungsbestaetigung','zahlungsquittung','rechnung','qr-rechnung','gutschrift','anreiseinformationen','reservationsofferte','anzahlungsrechnung','reservationsanderung','stornierungsbestatigung','zahlungserinnerung','erste-mahnung','zweite-mahnung','letzte-mahnung'].includes(id)){const records=id==='gastemeldeformular'?db.guests:['buchungsbestaetigung','anreiseinformationen','reservationsofferte','anzahlungsrechnung','reservationsanderung','stornierungsbestatigung'].includes(id)?db.bookings.filter(x=>id==='anzahlungsrechnung'?x.status!=='Storniert'&&Number(x.depositAmount)>0&&Boolean(x.depositDue):id!=='stornierungsbestatigung'||x.status==='Storniert'):id==='zahlungsquittung'?db.payments:['rechnung','zahlungserinnerung','qr-rechnung'].includes(id)?db.invoices:['erste-mahnung','zweite-mahnung','letzte-mahnung'].includes(id)?db.invoices.reduce((out,inv)=>out.concat((inv.reminders||[]).map((m,i)=>({id:inv.id+':'+i,level:Number(m.level),display:inv.number+' · Stufe '+m.level+' · '+money(m.amount)})).filter(x=>id==='erste-mahnung'?x.level===1:id==='zweite-mahnung'?x.level===2:x.level>=3)),[]):db.invoices.reduce((out,inv)=>out.concat((inv.credits||[]).map((c,i)=>({id:inv.id+':'+i,display:inv.number+' · '+c.number+' · '+money(c.amount)}))),[]);const title=DOCUMENT_TYPES.find(x=>x.id===id);if(!records.length){dialog('<h2>'+esc(title.name)+'</h2><p>Für diesen Bericht sind noch keine gespeicherten Datensätze vorhanden.</p>'+btn('Schliessen','close'));return}dialog('<h2>'+esc(title.name)+'</h2><form id="document-select-form"><label>Datensatz auswählen</label><select name="record" required>'+records.map(x=>'<option value="'+esc(x.id)+'">'+esc(id==='gastemeldeformular'?x.name:['buchungsbestaetigung','anreiseinformationen','reservationsofferte','anzahlungsrechnung','reservationsanderung','stornierungsbestatigung'].includes(id)?get('guests',x.guest).name+' · '+x.arrival:id==='zahlungsquittung'?get('invoices',x.invoice).number+' · '+money(x.amount):['rechnung','zahlungserinnerung','qr-rechnung'].includes(id)?x.number+' · '+(x.guest||'')+' · '+money(x.total):x.display)+'</option>').join('')+'</select><div class="actions"><button type="submit" class="primary">PDF-Vorschau öffnen</button>'+btn('Abbrechen','close')+'</div></form>');$('document-select-form').onsubmit=e=>{e.preventDefault();const picked=e.target.elements.record.value;close();documentPreview(id,picked)};return}if(id==='qr-rechnung'){qrDataView(selectedId);return}if(id==='rechnung'){invoice(selectedId);return}const doc=reportBuild(id,documentDay,selectedId);if(id==='jahresbelegungsubersicht'){documentZoom=100;documentReturnPage=page;documentLast=doc;document.body.classList.remove('reference-dashboard');document.body.classList.add('document-preview');$('main').innerHTML='<div class="pdf-preview-toolbar no-print"><strong>PDF-Vorschau · '+esc(doc.name)+'</strong><div class="actions">'+btn('Verkleinern','documentZoomOut')+btn('100 %','documentZoomReset')+btn('Vergrössern','documentZoomIn')+btn('PDF / Drucken','print')+btn('CSV teilen','documentCsv')+btn('Schliessen','documentClose')+'</div></div>'+annualOccupancyReport(doc);return}if(['buchungsbestaetigung','reservationsofferte','gutschrift','anzahlungsrechnung','zahlungserinnerung','erste-mahnung','zweite-mahnung','letzte-mahnung'].includes(id)){documentZoom=100;documentReturnPage=page;documentLast=doc;document.body.classList.remove('reference-dashboard');document.body.classList.add('document-preview');$('main').innerHTML='<div class="pdf-preview-toolbar no-print"><strong>PDF-Vorschau · '+esc(doc.name)+'</strong><div class="actions">'+btn('Verkleinern','documentZoomOut')+btn('100 %','documentZoomReset')+btn('Vergrössern','documentZoomIn')+btn('PDF / Drucken','print')+btn('CSV teilen','documentCsv')+btn('Schliessen','documentClose')+'</div></div>'+ (['buchungsbestaetigung','reservationsofferte'].includes(id)?reservationLetter(doc,selectedId):id==='gutschrift'?creditLetter(doc,selectedId):paymentLetter(doc,selectedId));return}documentZoom=100;documentReturnPage=page;documentLast=doc;document.body.classList.remove('reference-dashboard');document.body.classList.add('document-preview');$('main').innerHTML='<div class="pdf-preview-toolbar no-print"><strong>PDF-Vorschau · '+esc(doc.name)+'</strong><div class="actions">'+btn('Verkleinern','documentZoomOut')+btn('100 %','documentZoomReset')+btn('Vergrössern','documentZoomIn')+btn('PDF / Drucken','print')+btn('CSV teilen','documentCsv')+btn('Schliessen','documentClose')+'</div></div><article class="report-a4"><div class="report-topline"></div><div class="report-brand"><img class="app-brand-logo" src="app-logo.svg" alt="STAY Swiss"><div><strong>STAY Swiss</strong><small>HOTEL MANAGEMENT</small></div></div><div class="report-hotel"><strong>'+esc(db.hotel.name)+'</strong><div>'+esc(formattedAddress(db.hotel))+'</div><div>'+esc(db.hotel.email||'')+'</div></div><h1>'+esc(doc.name)+'</h1><div class="report-meta">Berichtsdatum: '+esc(doc.day)+' · Währung: CHF</div><div class="report-summary">'+esc(doc.summary)+'</div>'+(doc.rows.length?htmlTable(doc.columns,doc.rows):'<p class="report-empty">Keine entsprechenden Datensätze vorhanden.</p>')+'<p class="report-notes">'+esc(doc.notes)+'</p><footer class="report-footer">'+esc(db.hotel.name)+' · STAY Swiss · '+esc(doc.day)+'</footer></article>'}
function documentCsv(){if(!documentLast)return;const d=documentLast;const row=r=>r.map(v=>'"'+String(v==null?'':v).replace(/"/g,'""').replace(/^[=+@-]/,x=>"'"+x)+'"').join(';');const csv=[row(d.columns)].concat(d.rows.map(row)).join('\r\n');if(typeof Stay!=='undefined'&&typeof Stay.shareCsv==='function')Stay.shareCsv(d.id+'-'+d.day+'.csv','\uFEFF'+csv);else if(typeof Stay!=='undefined')Stay.share(csv);else{const link=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.href=url;link.download=d.id+'-'+d.day+'.csv';link.click();URL.revokeObjectURL(url)}}
