function changeDocumentZoom(delta){const main=$('main'),articles=main.querySelectorAll('.report-a4');if(!articles.length)return;documentZoom=delta===0?100:Math.max(50,Math.min(200,documentZoom+delta));articles.forEach(article=>{article.style.zoom=String(documentZoom/100)});const reset=main.querySelector('[data-action="documentZoomReset"]');if(reset){const label=reset.querySelector('span');if(label)label.textContent=documentZoom+' %';else reset.textContent=documentZoom+' %';reset.setAttribute('aria-label','Zoom '+documentZoom+' Prozent, zurücksetzen')}const minus=main.querySelector('[data-action="documentZoomOut"]'),plus=main.querySelector('[data-action="documentZoomIn"]');if(minus)minus.disabled=documentZoom<=50;if(plus)plus.disabled=documentZoom>=200}
