let touristTaxReportMonth=today().slice(0,7);
function touristTaxMonthRows(month){
 if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw Error('Ungültiger Berichtsmonat');
 const out=[];
 for(const b of db.bookings){
  if(['Anfrage','Storniert'].includes(b.status)||!b.priceSnapshot||!b.priceSnapshot.touristTaxDetails)continue;
  const t=b.priceSnapshot.touristTaxDetails;
  if(!t.enabled||!(Number(t.amount)>0))continue;
  const begin=Date.parse(b.arrival+'T12:00:00Z'),end=Date.parse(b.departure+'T12:00:00Z');
  if(!Number.isFinite(begin)||!Number.isFinite(end))continue;
  const monthStart=Date.parse(month+'-01T12:00:00Z');
  const monthEnd=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),1,12)).getTime();
  const first=Math.max(begin,monthStart),last=Math.min(end,monthEnd);
  const nightsInMonth=Math.max(0,Math.round((last-first)/86400000));
  if(!nightsInMonth)continue;
  const adultAmount=Math.round(Number(t.adults)*Number(t.adultRate)*100)*nightsInMonth;
  const childAmount=Math.round(Number(t.children)*Number(t.childRate)*100)*nightsInMonth;
  out.push({name:get('guests',b.guest).name||'Gast',room:get('rooms',b.room).number||'–',nights:nightsInMonth,adults:Number(t.adults),children:Number(t.children),adultAmount:chf(adultAmount),childAmount:chf(childAmount),total:chf(adultAmount+childAmount)});
 }
 return out;
}
function exportTouristTaxCsv(){
 const month=touristTaxReportMonth,rows=touristTaxMonthRows(month);
 const quote=v=>'"'+String(v==null?'':v).replace(/"/g,'""').replace(/^[=+@-]/,x=>"'"+x)+'"';
 const line=parts=>parts.map(quote).join(';');
 const data=[['Monat','Gast','Zimmer','Nächte','Erwachsene pflichtig','Kinder pflichtig','Erwachsene CHF','Kinder CHF','Gesamt CHF'],...rows.map(x=>[month,x.name,x.room,x.nights,x.adults,x.children,x.adultAmount.toFixed(2),x.childAmount.toFixed(2),x.total.toFixed(2)])];
 const csv='\uFEFF'+data.map(line).join('\r\n');
 if(typeof Stay!=='undefined'){if(typeof Stay.shareCsv==='function')Stay.shareCsv('stay-kurtaxe-planung-'+month+'.csv',csv);else Stay.share(csv);return}
 const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');
 link.href=url;link.download='stay-kurtaxe-planung-'+month+'.csv';link.click();URL.revokeObjectURL(url);
}
