function validateCashDays(days){const dates=new Set();for(const c of days){if(typeof c.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(c.date)||!Number.isFinite(Date.parse(c.date))||new Date(c.date).toISOString().slice(0,10)!==c.date||dates.has(c.date))throw Error('Ungültiger oder doppelter Kassentag');dates.add(c.date);if(typeof c.name!=='string'||!c.name.trim()||![c.opening,c.counted].every(v=>typeof v==='number'&&Number.isFinite(v)&&v>=0)||!Array.isArray(c.entries))throw Error('Ungültiger Kassenbestand');for(const e of c.entries){if(!e||!['Ein','Aus'].includes(e.kind)||typeof e.amount!=='number'||!Number.isFinite(e.amount)||e.amount<=0||typeof e.name!=='string'||!e.name.trim())throw Error('Ungültige Bargeldbewegung')}}return days}
function validateBackup(data){if(!data||typeof data!=='object'||Array.isArray(data))throw Error('Ungültige Sicherung');const result=empty(),ids={};for(const k of Object.keys(result)){if(k==='hotel')continue;if(data[k]===undefined&&['lostItems','guestWishes','maintenance','handover','cashDays','employees','accounts','staffReports','journal','shifts','absences',"suppliers","stockItems","stockMoves","inventories","purchaseOrders","recipes","recipeLines","menus","payrollDrafts","vendorBills","pdfLayouts"].includes(k))continue;if(!Array.isArray(data[k]))throw Error('Ungültige Tabelle: '+k);ids[k]=new Set();for(const row of data[k]){if(!row||typeof row!=='object'||typeof row.id!=='string'||!row.id||ids[k].has(row.id))throw Error('Ungültige oder doppelte ID: '+k);ids[k].add(row.id)}result[k]=data[k]}if(!data.hotel||typeof data.hotel.name!=='string')throw Error('Hotelprofil fehlt');for(const k of Object.keys(result.hotel)){if(Object.prototype.hasOwnProperty.call(data.hotel,k)){if(typeof data.hotel[k]!=='string')throw Error('Ungültiges Hotelprofil: '+k);result.hotel[k]=data.hotel[k]}}const link=(k,id)=>{if(!ids[k]?.has(id))throw Error('Fehlende Verknüpfung: '+k)};for(const b of result.bookings){link('guests',b.guest);link('rooms',b.room);for(const key of ['extraBreakfast','extraLunch','extraDinner']){if(b[key]===undefined)continue;const n=Number(b[key]);if(!Number.isInteger(n)||n<0||n>100)throw Error('Ungültige Zusatzmahlzeiten in Reservation');b[key]=n}if(b.extraMealDays!==undefined){if(typeof b.extraMealDays!=='string')throw Error('Ungültige Tagesabweichungen');extraMealOverrides(b)}if(b.depositAmount==null&&Number(b.deposit)>0)b.depositAmount=Number(b.deposit)}for(const i of result.invoices){link('bookings',i.booking);if(!Array.isArray(i.lines)||!Number.isFinite(Number(i.total))||Number(i.total)<0)throw Error('Ungültige Rechnung');for(const m of [...(Array.isArray(i.reminders)?i.reminders:[]),...(i.paymentNotice?[i.paymentNotice]:[])]){if(!m||typeof m!=='object')throw Error('Ungültiges Mahndokument');if(m.fee!==undefined)reminderFee(m.fee);if(m.dispatchHistory!==undefined&&(!Array.isArray(m.dispatchHistory)||m.dispatchHistory.some(v=>!v||typeof v.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||!['E-Mail','Post','Persönlich'].includes(v.channel)||typeof v.note!=='string'||typeof v.recordedAt!=='string')))throw Error('Ungültige Versandhistorie')}for(const key of ['credits','refunds']){if(i[key]===undefined)continue;if(!Array.isArray(i[key])||i[key].some(row=>!row||typeof row!=='object'||!Number.isFinite(Number(row.amount))||Number(row.amount)<=0))throw Error('Ungültige Rechnungsdaten: '+key)}}for(const p of result.payments){link('invoices',p.invoice);if(!Number.isFinite(Number(p.amount))||Number(p.amount)<=0)throw Error('Ungültige Zahlung')}for(const s of result.services)link('bookings',s.booking);for(const t of result.tasks)link('rooms',t.room);for(const t of result.maintenance)if(t.room)link('rooms',t.room);for(const t of result.guestWishes){if(t.room)link('rooms',t.room);if(t.guest)link('guests',t.guest)}validateCashDays(result.cashDays);if(result.hotel.financeLockedThrough&&(!/^\d{4}-\d{2}-\d{2}$/.test(result.hotel.financeLockedThrough)||!Number.isFinite(Date.parse(result.hotel.financeLockedThrough))||new Date(result.hotel.financeLockedThrough).toISOString().slice(0,10)!==result.hotel.financeLockedThrough))throw Error('Ungültiges Abschlussdatum');for(const r of [...result.shifts,...result.absences])link('employees',r.employee);for(const [table,refs] of Object.entries({"suppliers":[],"stockItems":[],"stockMoves":[["item","stockItems"]],"inventories":[["item","stockItems"]],"purchaseOrders":[["supplier","suppliers"],["item","stockItems"]],"recipes":[],"recipeLines":[["recipe","recipes"],["item","stockItems"]],"menus":[["recipe","recipes"]],"payrollDrafts":[["employee","employees"]],"vendorBills":[["supplier","suppliers"]],"pdfLayouts":[]})){for(const row of result[table])for(const [field,target] of refs)link(target,row[field])} const accountNumbers=new Set();for(const a of result.accounts){if(!/^\d{4,8}$/.test(a.number)||typeof a.name!=='string'||!a.name.trim()||accountNumbers.has(a.number)||!['Aktiven','Passiven','Ertrag','Aufwand'].includes(a.category)||!['Aktiv','Inaktiv'].includes(a.status))throw Error('Ungültiges oder doppeltes Konto');accountNumbers.add(a.number)}for(const j of result.journal){link('accounts',j.debit);link('accounts',j.credit);if(j.debit===j.credit||!Number.isFinite(Number(j.amount))||!Number.isSafeInteger(cents(j.amount))||cents(j.amount)<=0)throw Error('Ungültige Journalbuchung')}for(const r of result.staffReports){link('employees',r.employee);const mins=v=>{if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(v))throw Error('Ungültige Rapportzeit');const [h,m]=v.split(':').map(Number);return h*60+m};const pause=Number(r.breakMinutes),net=mins(r.end)-mins(r.start)-pause;if(!Number.isInteger(pause)||pause<0||net<=0||Number(r.workMinutes)!==net)throw Error('Ungültiger Mitarbeiterrapport')}return result}
