function creditNew(id){const x=get('invoices',id);const remaining=Math.round((x.total-credited(id))*100)/100;if(!x.id||remaining<=0)throw Error('Kein verbleibender Rechnungsbetrag für Gutschrift');dialog('<h2>Gutschrift erstellen</h2><p>Maximal '+money(remaining)+'</p><form id="credit-form"><label>Rechnungsposition</label><select name="line">'+x.lines.map((l,i)=>'<option value="'+i+'">'+esc(l.name)+' · '+money(l.amount)+'</option>').join('')+'</select><label>Betrag inklusive MWST</label><input name="amount" type="number" min="0.01" max="'+remaining+'" step="0.01" required><label>Begründung</label><textarea name="reason" required></textarea><div class="actions dialog-actions">'+btn('Abbrechen','close')+'<button class="primary" type="submit">Gutschrift speichern</button></div></form>');$('credit-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),i=Number(f.get('line')),l=x.lines[i],cents=Math.round(Number(f.get('amount'))*100),reason=String(f.get('reason')).trim(),history=x.credits||[];if(!l||!reason||!Number.isSafeInteger(cents)||cents<=0||cents>Math.round((x.total-credited(id))*100)||cents>Math.round(l.amount*100)-history.filter(c=>c.line===i).reduce((n,c)=>n+Math.round(c.amount*100),0))throw Error('Ungültiger Gutschriftbetrag');const c={number:'GS-'+x.number+'-'+(history.length+1),date:today(),line:i,name:l.name,vat:l.vat,taxTreatment:l.taxTreatment,amount:cents/100,reason};atomicChange(()=>{x.credits=history.concat(c)},'Gutschrift '+c.number+' erstellt');close();creditView(id,history.length)}catch(err){alert(err.message)}}}
function creditView(id,index){documentPreview('gutschrift',id+':'+index)}
function reminderDispatch(id){const [invoiceId,index]=id.split(':');const x=get('invoices',invoiceId),m=index==='notice'?x.paymentNotice:(x.reminders||[])[Number(index)];if(!m||(index!=='notice'&&![1,2,3].includes(Number(m.level))))throw Error('Ungültiges Mahndokument');dialog('<h2>Versand dokumentieren</h2><form id="dispatch-form" class="compact-editor columns-2"><label>Versanddatum</label><input name="date" type="date" max="'+today()+'" value="'+today()+'" required><label>Versandart</label><select name="channel"><option>E-Mail</option><option>Post</option><option>Persönlich</option></select><label>Notiz / Referenz</label><textarea name="note"></textarea><div class="actions">'+btn('Abbrechen','reminderArchive',invoiceId)+'<button type="submit" class="primary">Speichern</button></div></form>');$('dispatch-form').onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target).entries());if(!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||v.date>today()||v.date<(m.date||'')||!['E-Mail','Post','Persönlich'].includes(v.channel))throw Error('Ungültige Versandangaben');atomicChange(()=>{m.dispatchHistory=(Array.isArray(m.dispatchHistory)?m.dispatchHistory:[]).concat({date:v.date,channel:v.channel,note:v.note.trim(),recordedAt:new Date().toISOString()})},'Mahnversand manuell dokumentiert: '+(m.number||x.number));reminderArchive(invoiceId)}catch(err){alert(err.message)}}}
function reminderArchive(id){const x=get('invoices',id);if(!x.id)throw Error('Rechnung nicht gefunden');const rows=(x.reminders||[]).map((m,index)=>({m,index,title:['Erste Mahnung','Zweite Mahnung','Letzte Mahnung'][m.level-1]||'Unbekannte Mahnstufe'}));if(x.paymentNotice)rows.unshift({m:x.paymentNotice,index:'notice',title:'Zahlungserinnerung'});dialog('<h2>Mahndokumente · '+esc(x.number)+'</h2>'+ (rows.map(({m,index,title})=>'<div class="entry"><div><strong>'+esc(title)+' · '+esc(m.number||'–')+'</strong><small>'+esc(m.date||'–')+' · Frist '+esc(m.dueDate||'–')+' · '+money(m.amount||0)+'</small>'+ (Number(m.fee)>0?'<small>Mahngebühr: '+money(Number(m.fee))+' · separat, nicht verbucht</small>':'')+'<small>'+ (Array.isArray(m.dispatchHistory)&&m.dispatchHistory.length?'Versand manuell dokumentiert (kein Zustellnachweis)':'Versandstatus: nicht nachgewiesen')+'</small>'+ (Array.isArray(m.dispatchHistory)?m.dispatchHistory.map(v=>'<small>'+esc(v.date)+' · '+esc(v.channel)+' · '+esc(v.note||'')+'</small>').join(''):'')+'</div>'+ (index==='notice'||[1,2,3].includes(Number(m.level))?btn('PDF öffnen','reminderArchivePdf',id+':'+index)+btn('Versand erfassen','reminderDispatch',id+':'+index):'<small>Datensatz prüfen</small>')+'</div>').join('')||'<p>Keine Dokumente vorhanden.</p>')+'<div class="actions">'+btn('Schliessen','close')+'</div>')}
function reminderOverview(){const day=today(),rows=db.invoices.map(x=>{const amount=Math.max(0,Math.round((Number(x.total)-paid(x.id)-credited(x.id))*100)/100),history=x.reminders||[],last=history[history.length-1],due=last?last.dueDate||'':x.dueDate||'',ready=amount>0&&!!x.dueDate&&x.dueDate<day&&!!due&&due<day&&history.length<3&&history.every((entry,index)=>Number(entry.level)===index+1)&&(!last||last.date!==day);const needsReview=history.length>0&&(!due||!history.every((entry,index)=>Number(entry.level)===index+1));return {x,amount,history,last,due,ready,needsReview}}).filter(r=>r.amount>0||r.history.length||r.x.paymentNotice).sort((a,b)=>Number(b.ready)-Number(a.ready)||a.due.localeCompare(b.due));return '<div class="metrics">'+metric('Offene Forderungen',money(rows.reduce((n,r)=>n+r.amount,0)))+metric('Mahnung fällig',rows.filter(r=>r.ready).length)+metric('Erstellte Mahnungen',rows.reduce((n,r)=>n+r.history.length,0))+'</div>'+card('<h2>Mahnwesen</h2><div class="actions">'+btn('Einstellungen','go','settings')+'</div>'+ (rows.map(r=>{const x=r.x,b=get('bookings',x.booking),g=get('guests',b.guest);return '<div class="entry"><div><strong>'+esc(x.number)+' · '+esc(g.name||'Gast')+'</strong><small>Offen '+money(r.amount)+' · Frist '+esc(r.due||'–')+' · '+(r.needsReview?'Mahnverlauf prüfen':r.amount===0?'Beglichen':r.ready?'Mahnung fällig':r.history.length===3?'Letzte Mahnung erstellt':'Frist beachten')+'</small><small>'+esc(r.last?(['Erste Mahnung','Zweite Mahnung','Letzte Mahnung'][r.last.level-1]||'Unbekannte Mahnstufe'):'Keine Mahnung')+'</small></div><div class="actions">'+btn('Rechnung','invoice',x.id)+(r.ready?btn('Mahnung erstellen','reminder',x.id,'primary'):'')+(r.last||x.paymentNotice?btn('Archiv öffnen','reminderArchive',x.id):'')+'</div></div>'}).join('')||'<p>Keine offenen Forderungen oder Mahnungen.</p>'))}
function reminderSettings(h){return '<section class="reminder-settings"><h2>Mahnwesen · Einstellungen</h2><p>Standardtexte und Zahlungsfristen für neue Dokumente. Bereits erstellte Mahnungen bleiben unverändert.</p><div class="reminder-card-grid">'+[['notice','Zahlungserinnerung'],['reminder1','Erste Mahnung'],['reminder2','Zweite Mahnung'],['reminder3','Letzte Mahnung']].map(([k,title])=>'<section class="reminder-stage"><h3>'+title+'</h3><div class="reminder-stage-fields"><div class="hotel-profile-field"><label for="'+k+'Days">Frist in Tagen</label><input id="'+k+'Days" type="number" min="1" max="365" step="1" data-hotel="'+k+'Days" value="'+esc(h[k+'Days']||'10')+'"></div>'+(k==='notice'?'':'<div class="hotel-profile-field"><label for="'+k+'Fee">Mahngebühr CHF</label><input id="'+k+'Fee" type="number" min="0" max="9999" step="0.01" data-hotel="'+k+'Fee" value="'+esc(h[k+'Fee']||'0')+'"></div>')+'<div class="hotel-profile-field reminder-stage-text"><label for="'+k+'Text">Standardtext</label><textarea id="'+k+'Text" data-hotel="'+k+'Text" rows="3">'+esc(h[k+'Text']||'')+'</textarea></div></div></section>').join('')+'</div><div class="hotel-profile-field reminder-contact"><label for="reminderContact">Kontakt für Rückfragen</label><input id="reminderContact" data-hotel="reminderContact" value="'+esc(h.reminderContact||'')+'"></div></section>'}
function reminderFee(value){const n=Number(value??0);if(!Number.isFinite(n)||n<0||n>9999||Math.abs(n*100-Math.round(n*100))>0.000001)throw Error('Ungültige Mahngebühr (CHF 0–9999, maximal zwei Dezimalstellen)');return Math.round(n*100)/100}
function validateReminderSettings(h){for(const k of ['reminder1','reminder2','reminder3'])reminderFee(h[k+'Fee']);for(const k of ['notice','reminder1','reminder2','reminder3']){const n=Number(h[k+'Days']);if(!Number.isInteger(n)||n<1||n>365||!String(h[k+'Text']||'').trim())throw Error('Mahnwesen: Frist 1–365 Tage und Standardtext erforderlich')}}
function reminderDue(k){const n=Number(db.hotel[k+'Days']);return new Date(Date.parse(today()+'T12:00:00Z')+(Number.isInteger(n)&&n>=1&&n<=365?n:10)*86400000).toISOString().slice(0,10)}
function reminder(id){
 const x=get('invoices',id),amount=Math.round((x.total-paid(id)-credited(id))*100)/100;
 if(!x.id||!x.dueDate||x.dueDate>=today()||amount<=0)throw Error('Keine überfällige Forderung');
 const history=x.reminders||[],last=history[history.length-1],level=history.length+1;
 if(!history.every((entry,index)=>Number(entry.level)===index+1))throw Error('Mahnverlauf ist inkonsistent und muss geprüft werden');
 if(level>3)throw Error('Letzte Mahnung bereits erstellt');
 if(last&&(last.date===today()||!last.dueDate||last.dueDate>=today()))throw Error('Die bisherige Mahnfrist ist noch nicht abgelaufen');
 const title=['Erste Mahnung','Zweite Mahnung','Letzte Mahnung'][level-1],message=db.hotel['reminder'+level+'Text'],due=reminderDue('reminder'+level),fee=reminderFee(db.hotel['reminder'+level+'Fee']);
 dialog('<h2>'+title+'</h2><form id="reminder-form" class="compact-editor columns-2"><div class="editor-fields"><div class="editor-field"><label>Rechnung</label><input readonly value="'+esc(x.number)+'"></div><div class="editor-field"><label>Offener Betrag CHF</label><input readonly value="'+amount.toFixed(2)+'"></div><div class="editor-field"><label>Mahngebühr CHF (separat, nicht verbucht)</label><input readonly value="'+fee.toFixed(2)+'"></div><div class="editor-field"><label>Mahndatum</label><input readonly value="'+today()+'"></div><div class="editor-field"><label>Neue Zahlungsfrist</label><input name="dueDate" type="date" min="'+today()+'" value="'+due+'" required></div><div class="editor-field"><label>Kontakt bei Rückfragen</label><input name="contact" value="'+esc(db.hotel.reminderContact||['Rezeption',db.hotel.email,db.hotel.phone].filter(Boolean).join(' · '))+'"></div><div class="editor-field full-field"><label>Mahntext</label><textarea name="message" required>'+esc(message)+'</textarea></div></div><p id="reminder-error" role="alert"></p><div class="actions">'+btn('Abbrechen','close')+'<button type="submit" class="primary">Mahnung erstellen</button></div></form>');
 $('reminder-form').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target).entries());if(f.dueDate<=today()||!f.message.trim())throw Error('Zukünftige Zahlungsfrist und Mahntext erforderlich');const prefix=['ERS','ZWE','LET'][level-1]+'-'+today().slice(0,4)+'-',max=db.invoices.flatMap(i=>i.reminders||[]).reduce((n,m)=>String(m.number||'').startsWith(prefix)?Math.max(n,Number(m.number.slice(prefix.length))||0):n,0);const number=prefix+String(max+1).padStart(4,'0');atomicChange(()=>{x.reminders=history.concat({number,date:today(),level,amount,fee,dueDate:f.dueDate,message:f.message.trim(),contact:f.contact.trim()})},'Mahnung erstellt: '+number);close();showReminder(id)}catch(err){$('reminder-error').textContent=err.message}};
}
function showReminder(id){const x=get('invoices',id),history=x.reminders||[],m=history[history.length-1];if(!m)throw Error('Keine Mahnung vorhanden');documentPreview(m.level===1?'erste-mahnung':m.level===2?'zweite-mahnung':'letzte-mahnung',id+':'+(history.length-1))}
function swissIban(value){const iban=String(value||'').replace(/\s/g,'').toUpperCase();if(!/^(CH|LI)[0-9]{7}[A-Z0-9]{12}$/.test(iban))return false;let rem=0;for(const c of iban.slice(4)+iban.slice(0,4)){for(const digit of (/[A-Z]/.test(c)?String(c.charCodeAt(0)-55):c))rem=(rem*10+Number(digit))%97}return rem===1}
function isQrIban(value){const iban=String(value||'').replace(/\s/g,'').toUpperCase();return swissIban(iban)&&Number(iban.slice(4,9))>=30000&&Number(iban.slice(4,9))<=31999}
function nextInvoiceNumber(){const prefix='RE-'+new Date().getFullYear()+'-';const max=db.invoices.reduce((n,x)=>{const v=String(x.number||'');return v.startsWith(prefix)&&/^\d+$/.test(v.slice(prefix.length))?Math.max(n,Number(v.slice(prefix.length))):n},0);if(!Number.isSafeInteger(max+1))throw Error('Rechnungsnummernkreis erschöpft');return prefix+String(max+1).padStart(4,'0')}
function qrReference(number){const raw=String(number||'');if(!/^RE-\d{4}-\d+$/.test(raw))throw Error('Rechnungsnummer für QR-Referenz nicht unterstützt');const digits=raw.replace(/\D/g,'');if(digits.length>26)throw Error('Rechnungsnummer zu lang');const base=digits.padStart(26,'0'),table=[0,9,4,6,8,2,7,1,3,5];let carry=0;for(const d of base)carry=table[(carry+Number(d))%10];return base+String((10-carry)%10)}
function qrPaymentData(id){const x=get('invoices',id),h=x.issuer||db.hotel,iban=String(h.qrIban||h.iban||'').replace(/\s/g,'').toUpperCase(),amount=Math.round((x.total-paid(id)-credited(id))*100)/100;if(!swissIban(iban))throw Error('Gültige Schweizer oder Liechtensteiner IBAN erforderlich');const qr=isQrIban(iban),reference=qr?qrReference(x.number):'';if(qr&&db.invoices.some(other=>other.id!==id&&other.number===x.number))throw Error('Doppelte Rechnungsnummer');if(!Number.isFinite(amount)||amount<=0||amount>999999999.99)throw Error('Ungültiger offener Betrag');if(![h.name,h.postalCode,h.city,h.street].every(v=>String(v||'').trim()))throw Error('Strukturierte Hoteladresse in Einstellungen erforderlich');const clean=(v,max)=>{const t=String(v||'').trim();if(/[\r\n]/.test(t)||t.length>max)throw Error('Adressfeld oder Referenz ungültig');return t};const country=h.country||'CH';if(!/^[A-Z]{2}$/.test(country))throw Error('Ländercode ungültig');return ['SPC','0200','1',iban,'S',clean(h.name,70),clean(h.street,70),clean(h.houseNumber,16),clean(h.postalCode,16),clean(h.city,35),country,'','','','','','','',amount.toFixed(2),'CHF','','','','','','','',qr?'QRR':'NON',reference,clean(x.number,140),'EPD'].join('\r\n')}
function qrDataView(id){const x=get('invoices',id);if(!x.id)throw Error('Rechnung nicht gefunden');const h=x.issuer||db.hotel,amount=Math.max(0,Math.round((x.total-paid(id)-credited(id))*100)/100);let svg='',warning='',reference='';try{const data=qrPaymentData(id);reference=isQrIban(h.qrIban||h.iban)?qrReference(x.number):'';svg=typeof Stay!=='undefined'&&typeof Stay.qrSvg==='function'?Stay.qrSvg(data):'';if(!svg)warning='QR-Code-Erzeugung in dieser App-Version nicht verfügbar.'}catch(e){warning=e.message}close();documentZoom=100;documentReturnPage=page;documentLast=null;document.body.classList.remove('reference-dashboard');document.body.classList.add('document-preview');const address='<p><b>Konto / Zahlbar an</b><br>'+esc(h.qrIban||h.iban||'IBAN fehlt')+'<br>'+esc(h.name||'')+'<br>'+esc(formattedAddress(h))+'</p>',sum='<p><b>CHF '+amount.toFixed(2)+'</b></p>',debtor='<p><b>Zahlbar durch</b><br>'+esc(x.guest||'')+'</p>'; $('main').innerHTML='<div class="pdf-preview-toolbar no-print"><strong>PDF-Vorschau · Schweizer QR-Rechnung</strong><div class="actions">'+btn('Verkleinern','documentZoomOut')+btn('100 %','documentZoomReset')+btn('Vergrössern','documentZoomIn')+btn('PDF / Drucken','print')+btn('Schliessen','documentClose')+'</div></div><article class="report-a4 qr-invoice-report"><div class="report-topline"></div><div class="report-brand"><img class="app-brand-logo" src="app-logo.svg" alt="STAY Swiss"><div><strong>STAY Swiss</strong><small>HOTEL MANAGEMENT</small></div></div><div class="report-hotel"><strong>'+esc(h.name||'')+'</strong><div>'+esc(formattedAddress(h))+'</div></div><h1>Schweizer QR-Rechnung</h1><div class="report-meta">'+esc(x.number+' · '+(x.guest||'')+' · '+(x.arrival||'')+' – '+(x.departure||''))+'</div>'+htmlTable(['Leistung','MWST','CHF'],(x.lines||[]).map(l=>[l.name,l.taxTreatment==='pass_through'?'–':String(l.vat||0)+' %',Number(l.amount||0).toFixed(2)]))+htmlTable(['MWST-Satz','Netto CHF','Steuer CHF'],invoiceTax(x.lines||[]).map(t=>[t.rate+' %',t.net.toFixed(2),t.tax.toFixed(2)]))+'<div class="report-summary">Total '+money(x.total)+' · Bezahlt '+money(paid(id))+' · Gutschriften '+money(credited(id))+'<h2>Offen '+money(amount)+'</h2></div><p>Zahlbar bis '+esc(x.dueDate||'–')+'</p><div class="qr-sheet"><h3>QR-Zahlteil – Testentwurf</h3><div class="qr-strip"><section class="qr-receipt"><h2>Empfangsschein</h2>'+address+(reference?'<p><b>Referenz</b><br>'+esc(reference)+'</p>':'')+debtor+sum+'</section><section class="qr-part"><h2>Zahlteil</h2><div class="qr-columns"><div class="qr-left">'+(svg?'<div class="qr-code"><img class="qr-payment-image" alt="Swiss QR-Code" src="' + esc("data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg)) + '"><span class="qr-cross"></span></div>':'<div class="qr-blank">QR-Code nicht verfügbar</div>')+sum+'</div><div class="qr-right">'+address+debtor+'<p><b>'+ (reference?'Referenz':'Zusätzliche Informationen')+'</b><br>'+esc(reference||x.number)+'</p></div></div></section></div><p>TESTENTWURF – nicht für Zahlungsverkehr freigegeben. '+esc(warning)+'</p></div><footer class="report-footer">STAY Swiss · '+esc(x.date||'')+'</footer></article>'}
function invoiceDue(day){const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+30);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function invoiceTax(lines){const groups={};lines.filter(l=>l.taxTreatment!=='pass_through').forEach(l=>{const rate=Number(l.vat),gross=Math.round(Number(l.amount)*100);groups[rate]=(groups[rate]||0)+gross});return Object.keys(groups).map(k=>{const gross=groups[k],tax=Math.round(gross*Number(k)/(100+Number(k)));return {rate:Number(k),gross:gross/100,net:(gross-tax)/100,tax:tax/100}}).sort((a,b)=>a.rate-b.rate)}
function refundNew(id){const inv=get('invoices',id),limit=cents(paid(id))+cents(credited(id))-cents(inv.total);if(!inv.id||limit<=0)throw Error('Keine rückzahlbare Überzahlung vorhanden');dialog('<h2>Rückerstattung erfassen</h2><p>Nur bereits ausgeführte Rückzahlungen dokumentieren. Maximal '+money(chf(limit))+'</p><form id="refund-form"><label>Betrag CHF</label><input name="amount" type="number" min="0.01" max="'+chf(limit)+'" step="0.01" required><label>Auszahlungsdatum</label><input name="date" type="date" max="'+today()+'" value="'+today()+'" required><label>Zahlungsart</label><select name="method"><option>Banküberweisung</option><option>Bar</option><option>Karte</option><option>TWINT</option></select><label>Zahlungsnachweis / Referenz</label><input name="reference" required><label>Begründung</label><textarea name="reason" required></textarea><div class="actions"><button type="submit">Rückzahlung speichern</button>'+btn('Abbrechen','close')+'</div></form>');$('refund-form').onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target).entries()),amount=cents(v.amount),max=cents(paid(id))+cents(credited(id))-cents(inv.total);if(!Number.isSafeInteger(amount)||amount<=0||amount>max||!v.date||v.date>today()||!v.reference.trim()||!v.reason.trim())throw Error('Ungültige Rückzahlung');const history=inv.refunds||[],r={...v,amount:chf(amount),number:'RS-'+inv.number+'-'+(history.length+1)};atomicChange(()=>{inv.refunds=history.concat(r)},'Rückerstattung '+r.number+' erfasst');close();documentPreview('ruckerstattungsbeleg',id+':'+history.length)}catch(err){alert(err.message)}}}
function invoice(id){const x=get('invoices',id);if(!x.id)throw Error('Rechnung nicht gefunden');const tax=invoiceTax(x.lines),issuer=x.issuer||db.hotel,net=cents(x.total)-tax.reduce((n,t)=>n+cents(t.tax),0),balance=cents(x.total)-cents(paid(id))-cents(credited(id));close();documentZoom=100;documentReturnPage=page;documentLast={id:'rechnung',day:x.date,columns:['Leistung','Menge','Einzelpreis CHF','MWST','Brutto CHF'],rows:x.lines.map(l=>[l.name,l.quantity||1,Number(l.amount/(l.quantity||1)).toFixed(2),l.taxTreatment==='pass_through'?'–':l.vat+' %',Number(l.amount).toFixed(2)])};document.body.classList.remove('reference-dashboard');document.body.classList.add('document-preview');const meta=(k,v)=>'<dt>'+esc(k)+'</dt><dd>'+esc(v||'–')+'</dd>',sum=(k,v)=>'<div><span>'+esc(k)+'</span><strong>'+money(v)+'</strong></div>';$('main').innerHTML='<div class="pdf-preview-toolbar no-print"><strong>PDF-Vorschau · '+esc(x.number)+'</strong><div class="actions">'+btn('Verkleinern','documentZoomOut')+btn('100 %','documentZoomReset')+btn('Vergrössern','documentZoomIn')+btn('PDF / Drucken','print')+btn('CSV teilen','documentCsv')+btn('Schliessen','documentClose')+'</div></div><article class="report-a4 invoice-report"><div class="report-topline"></div><header class="invoice-letterhead"><div class="invoice-brand"><img class="app-brand-logo" src="app-logo.svg" alt="STAY Swiss"><div><strong>STAY Swiss</strong><small>HOTEL MANAGEMENT</small></div></div><div class="invoice-issuer"><strong>'+esc(issuer.name)+'</strong><div>'+esc(issuer.address||formattedAddress(issuer))+'</div><div>'+esc(issuer.vat||'')+'</div><div>'+esc([issuer.email,issuer.phone].filter(Boolean).join(' · '))+'</div></div></header><div class="invoice-address-block"><span>Rechnung an</span><strong>'+esc(x.guest||'–')+'</strong><div>'+esc(x.guestAddress||'')+'</div></div><h1>Gastrechnung</h1><dl class="invoice-meta">'+meta('Rechnungsnummer',x.number)+meta('Aufenthalt',swissDate(x.arrival)+' – '+swissDate(x.departure)+' · Zimmer '+(x.roomNumber||'–'))+meta('Rechnungsdatum',swissDate(x.date))+meta('Fällig',swissDate(x.dueDate))+'</dl>'+htmlTable(documentLast.columns,documentLast.rows)+'<div class="invoice-bottom"><div><h3>Hinweise</h3><p>Währung: CHF</p><p>IBAN: '+esc(issuer.iban||'–')+'</p><p>Zahlungsreferenz: '+esc(x.number)+'</p></div><div class="invoice-totals">'+sum('Netto inkl. separater Abgaben',chf(net))+tax.map(t=>sum('MWST '+t.rate+' %',t.tax)).join('')+sum('Brutto',x.total)+sum('Bezahlt',paid(id))+(credited(id)?sum('Gutschriften',credited(id)):'')+sum(balance<0?'Überzahlung':'Offen',chf(Math.abs(balance)))+'</div></div><footer class="report-footer">'+esc(issuer.name)+' · STAY Swiss</footer></article><div class="actions no-print invoice-management">'+btn('PDF / Drucken','print')+(x.total-paid(id)-credited(id)>0?btn('QR-Zahlungsdaten','qrData',id):'')+(cents(x.total)>cents(credited(id))?btn('Gutschrift erstellen','creditNew',id):'')+(x.credits||[]).map((c,i)=>btn(c.number,'creditView',id+':'+i)).join('')+(paid(id)+credited(id)>x.total?btn('Rückerstattung erfassen','refundNew',id):'')+(x.refunds||[]).map((r,i)=>btn(r.number,'refundView',id+':'+i)).join('')+((x.reminders||[]).length?btn('Letzte Mahnung','showReminder',id):'')+(x.dueDate&&x.dueDate<today()&&Math.round((x.total-paid(id)-credited(id))*100)>0?btn('Mahnung erstellen','reminder',id):'')+(x.total-paid(id)-credited(id)>0?btn('Zahlung erfassen','invoicePayment',id):'')+'</div>'}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action,id=b.dataset.id;try{if(a==='go'){close();navigate(id)}else if(a==='calendarWeek'){if(id==='0'){calendarAnchor='';weekOffset=0}else weekOffset+=Number(id);render()}else if(a==='calendarSpan'){calendarSpan=[7,14,31].includes(Number(id))?Number(id):7;weekOffset=0;render()}else if(a==='calendarMove'){calendarChange(id,'room')}else if(a==='calendarExtend'){calendarChange(id,'departure')}else if(a==='calendarShorten'){calendarChange(id,'shorten')}else if(a==='calendarDetail'){calendarDetail(get('bookings',id))}else if(a==='calendarNew'){const [room,day]=id.split(':');openCalendarReservation(room,day)}else if(a==='documentSection'){if(DOCUMENT_TYPES.some(x=>x.section===id)){documentSection=id;render()}}else if(a==='listPage'){listPage=Number(id)||1;if($('results')&&schemas[page])$('results').innerHTML=list(page)}else if(a==='tab'){tab=id;render()}else if(a==='accountLedger')accountLedger(id);else if(a==='lockFinancePeriod')lockFinancePeriod();else if(a==='vatOverview')vatOverview();else if(a==='financeStatements')financeStatements();else if(a==='trialBalance')trialBalance();else if(a==='importHotelAccounts')importHotelAccounts();else if(a==='roomTariff')showRoomTariff(id);else if(a==='edit'){const [k,i]=id.split(':');edit(k,i)}else if(a==='receptionFilter'){receptionFilter=id;query='';render()}else if(a==='reception')receptionAction(id);else if(a==='stayTransition'){const parts=id.split(':');transitionStay(parts[0],parts[1])}else if(a==='receptionSearch'){query=$('reception-search').value;close();render()}else if(a==='mealPrint')mealPrint(mealPlan(mealDay));else if(a==='mealDate')selectMealDay();else if(a==='mealCsv')mealExport(mealPlan(mealDay));else if(a==='close')close();else if(a==='delete'){const [k,i]=id.split(':');if(k==='journal'||k==='employees'&&[...db.staffReports,...db.shifts,...db.absences].some(r=>r.employee===i)||k==='accounts'&&db.journal.some(r=>r.debit===i||r.credit===i)||k==='payments'||k==='bookings'&&db.invoices.some(x=>x.booking===i)||k==='guests'&&(db.bookings.some(x=>x.guest===i)||db.guestWishes.some(x=>x.guest===i))||k==='rooms'&&(db.bookings.some(x=>x.room===i)||db.tasks.some(x=>x.room===i)||db.maintenance.some(x=>x.room===i)||db.guestWishes.some(x=>x.room===i))||k==='services'&&db.invoices.some(x=>x.booking===get(k,i).booking))throw Error('Verknüpfte oder finanzielle Daten dürfen nicht gelöscht werden');if(confirm('Eintrag löschen?')){db[k]=db[k].filter(x=>x.id!==i);log('Eintrag gelöscht');close();render()}}else if(a==='invoiceNew')invoiceNew();else if(a==='invoiceCreate'){const b=get('bookings',$('billBooking').value);if(!b.id)throw Error('Reservation auswählen');const isSnapshot=Boolean(b.priceSnapshot&&Number.isFinite(Number(b.priceSnapshot.lodging)));const q=isSnapshot?b.priceSnapshot:((rate)=>({nights:nights(b),adults:Number(b.people||1),children:0,lodging:chf(cents(nights(b)*rate)),breakfast:0,other:0}))(Number(b.rate==null?get('rooms',b.room).rate:b.rate));const lines=[{name:q.nights+' Übernachtungen'+(isSnapshot?' · '+q.adults+' Erw. / '+q.children+' Kinder':''),vat:VAT_LODGING,quantity:q.nights,amount:q.lodging}];const extra=q.extraMeals||{},eb=cents(extra.breakfast||0),el=cents(extra.lunch||0),ed=cents(extra.dinner||0),baseBreakfast=cents(q.breakfast)-eb,baseOther=cents(q.other)-el-ed;if([eb,el,ed,baseBreakfast,baseOther].some(v=>!Number.isFinite(v)||v<0))throw Error('Ungültige gespeicherte Verpflegungspreise');if(baseBreakfast>0)lines.push({name:'Frühstück · '+q.nights+' Nächte',vat:VAT_LODGING,amount:chf(baseBreakfast)});if(baseOther>0)lines.push({name:(b.meal==='Vollpension'?'Mittag- und Abendessen':'Zusätzliche Mahlzeit')+' · '+q.nights+' Nächte',vat:VAT_CATERING,amount:chf(baseOther)});for(const [name,amount,vat] of [['Zusatzfrühstück',eb,VAT_LODGING],['Zusatzmittagessen',el,VAT_CATERING],['Zusatzabendessen',ed,VAT_CATERING]])if(amount>0)lines.push({name,vat,amount:chf(amount)});if(Number(q.touristTax||0)>0)lines.push({name:'Kurtaxe / Gästetaxe · '+q.nights+' Nächte (separat)',vat:0,taxTreatment:'pass_through',amount:Number(q.touristTax)});lines.push(...db.services.filter(s=>s.booking===b.id).map(s=>({name:s.name,vat:Number(s.vat),amount:Number(s.amount)})));const x={id:uid(),number:nextInvoiceNumber(),booking:b.id,guest:get('guests',b.guest).name,guestAddress:formattedAddress(get('guests',b.guest)),issuer:Object.assign({},db.hotel),arrival:b.arrival,departure:b.departure,roomNumber:get('rooms',b.room).number,roomCategory:get('rooms',b.room).category,date:today(),dueDate:invoiceDue(today()),lines,total:Math.round(lines.reduce((s,l)=>s+l.amount,0)*100)/100};atomicChange(()=>{if(db.invoices.some(i=>i.booking===b.id)||['Storniert','Anfrage'].includes(b.status))throw Error('Reservation nicht abrechenbar');if(!Number.isFinite(x.total)||x.total<0||lines.some(l=>!Number.isFinite(l.amount)||l.amount<0||![0,2.6,3.8,8.1].includes(Number(l.vat))))throw Error('Ungültige Rechnungsposition');db.invoices.push(x)},'Rechnung erstellt');invoice(x.id)}else if(a==='qrData')qrDataView(id);else if(a==='refundView')documentPreview('ruckerstattungsbeleg',id);else if(a==='refundNew')refundNew(id);else if(a==='creditNew')creditNew(id);else if(a==='creditView'){const p=id.split(':');creditView(p[0],Number(p[1]))}else if(a==='reminder')reminder(id);else if(a==='showReminder')showReminder(id);else if(a==='reminderArchive')reminderArchive(id);else if(a==='reminderDispatch')reminderDispatch(id);else if(a==='reminderArchivePdf'){const [invoiceId,index]=id.split(':');const x=get('invoices',invoiceId),m=(x.reminders||[])[Number(index)];if(index==='notice'&&x.paymentNotice){close();documentPreview('zahlungserinnerung',invoiceId+':notice')}else if(m&&[1,2,3].includes(Number(m.level))){close();documentPreview(['erste-mahnung','zweite-mahnung','letzte-mahnung'][m.level-1],id)}else throw Error('Mahndokument fehlt oder Mahnstufe ist ungültig')}else if(a==='invoicePayment'){edit('payments');const field=$('editor').querySelector('[name="invoice"]');field.value=id;const amount=$('editor').querySelector('[name="amount"]');amount.value=Math.max(0,Math.round((get('invoices',id).total-paid(id)-credited(id))*100)/100).toFixed(2)}else if(a==='invoice')invoice(id);else if(a==='mailPreview')previewMail(id);else if(a==='mailCompose'){const recipient=$('mail-to')?.value||'',subject=$('mail-subject')?.value||'',body=$('mail-body')?.value||'';if(recipient&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient))throw Error('Ungültige E-Mail-Adresse');if(typeof Stay!=='undefined'&&typeof Stay.email==='function'){Stay.email(recipient,subject,body)}else if(typeof Stay!=='undefined'){Stay.share('Betreff: '+subject+'\n\n'+body)}else{window.location.href='mailto:'+encodeURIComponent(recipient)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}}else if(a==='documentPreview')documentPreview(id);else if(a==='documentZoomIn')changeDocumentZoom(25);else if(a==='documentZoomOut')changeDocumentZoom(-25);else if(a==='documentZoomReset')changeDocumentZoom(0);else if(a==='documentClose')documentClose();else if(a==='documentPickDate')documentPickDate();else if(a==='documentCsv')documentCsv();else if(a==='touristTaxCsv')exportTouristTaxCsv();else if(a==='support'){if(typeof Stay!=='undefined'&&typeof Stay.openExternal==='function')Stay.openExternal('https://buymeacoffee.com/swisstech');else window.open('https://buymeacoffee.com/swisstech','_blank','noopener,noreferrer')}else if(a==='hotelSave'){const changed=Object.assign({},db.hotel);document.querySelectorAll('[data-hotel]').forEach(x=>changed[x.dataset.hotel]=x.value);document.querySelectorAll('.meal-price-settings [name], .tourist-tax-settings [name]').forEach(x=>changed[x.name]=x.value);changed.qrIban=String(changed.qrIban||'').replace(/\s/g,'').toUpperCase();if(changed.qrIban&&!isQrIban(changed.qrIban))throw Error('Ungültige QR-IBAN: Schweizer oder Liechtensteiner QR-IBAN erforderlich');validateMealPrices(changed);validateTouristTax(changed);validateReminderSettings(changed);changed.address=formattedAddress(changed);atomicChange(()=>{db.hotel=changed},'Hoteleinstellungen gespeichert');alert('Einstellungen gespeichert')}else if(a==='print'){if(typeof Stay!=='undefined')Stay.print();else window.print()}else if(a==='backup'){if(typeof Stay!=='undefined')Stay.share(JSON.stringify(db));else{const l=document.createElement('a');l.href=URL.createObjectURL(new Blob([JSON.stringify(db)],{type:'application/json'}));l.download='stay-backup.json';l.click();URL.revokeObjectURL(l.href)}}}catch(err){alert(err.message)}});
$('search').onclick=()=>{dialog('<h2>Globale Suche</h2><section class="global-search"><p>Gäste, Zimmer, Reservationen und Rechnungen durchsuchen.</p><label for="global">Suchbegriff</label><input id="global" type="search" placeholder="Name, Zimmer- oder Rechnungsnummer" autocomplete="off"><label for="global-category">Bereich</label><select id="global-category"><option value="">Alle Bereiche</option><option value="guests">Gäste</option><option value="rooms">Zimmer</option><option value="bookings">Reservationen</option><option value="invoices">Rechnungen</option></select><div id="hits" aria-live="polite"></div></section>');const run=()=>{const q=$('global').value.trim().toLowerCase(),category=$('global-category').value,box=$('hits');if(q.length<2){box.textContent='Mindestens zwei Zeichen eingeben.';return}const fields={guests:['name','email','phone'],rooms:['number','category'],bookings:['id','groupRef','status'],invoices:['number','guest']};const hits=Object.keys(fields).filter(k=>!category||category===k).flatMap(k=>db[k].filter(x=>fields[k].map(key=>x[key]||'').concat(k==='bookings'?[get('guests',x.guest).name,get('rooms',x.room).number]:[]).join(' ').toLowerCase().includes(q)).map(x=>({k,x})));box.innerHTML=hits.length?'<p>'+hits.length+' Treffer'+(hits.length>50?' · erste 50 angezeigt':'')+'</p>'+hits.slice(0,50).map(({k,x})=>entry(label(k,x),{guests:'Gast',rooms:'Zimmer',bookings:'Reservation',invoices:'Rechnung'}[k],k==='invoices'?'invoice':'edit',k==='invoices'?x.id:k+':'+x.id)).join(''):'<p>Keine passenden Ergebnisse gefunden.</p>'};$('global').oninput=run;$('global-category').onchange=run;run();$('global').focus()};
