function startBooking(preset={}){if(!close())return;draft={id:uid(),guest:'',room:'',arrival:today(),departure:'',people:1,adults:1,children:0,taxExemptAdults:0,taxExemptChildren:0,meal:'Nur Logis',status:'Bestätigt',rate:'',depositAmount:0,depositDue:'',groupRef:'',...preset};navigate('bookingDraft')}
function renderBookingDraft(){
 if(!draft){navigate('bookings');return}
 document.body.classList.add('reference-dashboard');$('main').innerHTML=bookingReference;
 const svg=$('main').querySelector('svg'), main=svg.querySelector('#main-view'), work=svg.querySelector('#workspace-view');
 const set=(g,x,y,v)=>{const t=g.querySelector('text[x="'+x+'"][y="'+y+'"]');if(t)t.textContent=v};
 const bind=bindSvgAction;
 const date=v=>v?swissDate(v):'Auswählen';
 const opts=(items,v)=>'<option value="">Auswählen</option>'+items.map(x=>'<option value="'+esc(x[0])+'" '+(String(x[0])===String(v)?'selected':'')+'>'+esc(x[1])+'</option>').join('');
 const select=(k,items)=>'<select required name="'+k+'">'+opts(items,draft[k])+'</select>';
 const input=(k,type,extra='')=>'<input required name="'+k+'" type="'+type+'" value="'+esc(draft[k])+'" '+extra+'>';
 const meals=['Nur Logis','Frühstück','Halbpension','Vollpension'];
 function field(i){const forms=[select('guest',db.guests.map(g=>[g.id,g.name])), '<label>Anreise</label>'+input('arrival','date')+'<label>Abreise</label>'+input('departure','date'),'<label>Zimmer</label>'+select('room',db.rooms.filter(r=>r.status!=='Gesperrt').map(r=>[r.id,r.number+' · '+r.category]))+'<label>Erwachsene (1–6)</label>'+input('adults','number','min="1" max="6" step="1"')+'<label>Kinder (0–4)</label>'+input('children','number','min="0" max="4" step="1"')+'<label>Kurtaxenbefreite Erwachsene</label>'+input('taxExemptAdults','number','min="0" step="1"')+'<label>Kurtaxenbefreite Kinder</label>'+input('taxExemptChildren','number','min="0" step="1"'),select('meal',meals.map(m=>[m,m]))+['extraBreakfast','extraLunch','extraDinner'].map((k,i)=>'<label>'+['Zusatzfrühstück','Zusatzmittagessen','Zusatzabendessen'][i]+' pro Tag</label><input name="'+k+'" type="number" min="0" max="100" step="1" value="'+esc(draft[k]||0)+'">').join('')+'<label>Tagesabweichungen (Datum; Frühstück; Mittag; Abend)</label><textarea name="extraMealDays">'+esc(draft.extraMealDays||'')+'</textarea>','<p>Zimmerpreis ohne Verpflegung. Preisstaffel, Wochenende und Saison werden automatisch berechnet.</p><label>Vorgesehene Anzahlung CHF</label>'+input('depositAmount','number','min="0" step="0.01"')+'<label>Anzahlung fällig am</label><input name="depositDue" type="date" value="'+esc(draft.depositDue)+'"><label>Gruppenreferenz (optional)</label><input name="groupRef" maxlength="80" value="'+esc(draft.groupRef)+'">'];dialog('<h2>'+['Gast','Anreise / Abreise','Zimmer / Personen','Verpflegung','Tarif / Anzahlung'][i]+'</h2><form id="draft-field">'+forms[i]+'<div class="actions">'+btn('Abbrechen','close')+'<button type="submit" class="primary">Übernehmen</button></div></form>');$('draft-field').onsubmit=e=>{e.preventDefault();const old=draft.room;new FormData(e.target).forEach((v,k)=>draft[k]=v);if(i===2&&old!==draft.room)draft.rate=get('rooms',draft.room).rate;close();renderBookingDraft()}}
 function persist(){try{if(!get('guests',draft.guest).id||!get('rooms',draft.room).id)throw Error('Gast und Zimmer auswählen');const occ=occupancy(draft);draft.people=occ.people;const q=bookingQuote(draft,get('rooms',draft.room),db.hotel);draft.priceSnapshot=q;if(get('rooms',draft.room).status==='Gesperrt'||db.bookings.some(b=>b.room===draft.room&&active(b)&&overlap(b,draft)))throw Error('Zimmer nicht verfügbar: Doppelbuchung');if(!Number.isFinite(Number(draft.depositAmount))||Number(draft.depositAmount)<0||Number(draft.depositAmount)>q.total)throw Error('Anzahlung ungültig');if(Number(draft.depositAmount)>0&&!draft.depositDue)throw Error('Fälligkeitsdatum der Anzahlung fehlt');draft.groupRef=String(draft.groupRef||'').trim();if(draft.groupRef.length>80)throw Error('Gruppenreferenz zu lang');const old=JSON.stringify(db);try{db.bookings.push(Object.assign({},draft));log('Reservation erstellt')}catch(e){db=JSON.parse(old);throw e}draft=null;navigate('bookings')}catch(e){alert(e.message)}}
 const room=get('rooms',draft.room);
 [get('guests',draft.guest).name||'Gast auswählen',date(draft.arrival)+' – '+date(draft.departure),room.id?room.number+' · '+room.category+' · '+(Number(draft.adults)||1)+' Erw. / '+(Number(draft.children)||0)+' Kinder':'Zimmer auswählen',draft.meal,room.id&&draft.departure?money(bookingQuote(draft,room,db.hotel).total)+' / Anzahlung '+money(draft.depositAmount):'Preis wird berechnet'].forEach((v,i)=>set(main,71,383+i*70,v));
 set(main,16,132,'Entwurf · '+db.hotel.name);set(work,16,132,'Entwurf · '+db.hotel.name);
 main.querySelectorAll('g[tabindex]').forEach((g,i)=>bind(g,()=>field(i)));
 const routes={'01-dashboard.svg':'dashboard','06-kalender.svg':'calendar','03-buchungen.svg':'bookings','09-rechnungen.svg':'invoices','19-menu.svg':'more','22-systemmeldungen.svg':'logs'};
 svg.querySelectorAll('a').forEach(a=>{const t=(a.querySelector('title')||{}).textContent,h=a.getAttribute('href');bind(a,()=>{if(t==='Reservation speichern')persist();else if(h==='#main-view'||h==='#workspace-view'){tab=h==='#main-view'?'overview':'work';renderBookingDraft()}else if(h==='08-suche.svg')$('search').click();else if(routes[h]){if(confirm('Entwurf verlassen?')){draft=null;navigate(routes[h])}}else if(h==='20-pdf-vollbild.svg')window.print();else field(3)})});
 work.querySelectorAll('g[tabindex]').forEach(g=>bind(g,()=>field(3)));main.setAttribute('display',tab==='work'?'none':'inline');work.setAttribute('display',tab==='work'?'inline':'none');
}


