 const choose=k=>{receptionFilter=k;renderReception()};const listAll=()=>dialog('<h2>Aufenthalte</h2>'+rows.map(b=>entry(label('bookings',b),b.status,'reception',b.id)).join('')+btn('Schliessen','close'));
 const search=()=>{dialog('<h2>Aufenthalte suchen</h2><input id="reception-search" value="'+esc(query)+'">'+btn('Übernehmen','receptionSearch'));};
 [arrivals.length,departures.length,done.length,arrivals.length+departures.length].forEach((v,i)=>set(m,i%2?215:29,i<2?264:348,v));[arrivals.length,departures.length,done.length].forEach((v,i)=>set(w,128+i*112,284,v));for(const g of [m,w])set(g,16,132,new Date().toLocaleDateString('de-CH'));
 set(m,16,492,({arrivals:'Anreisen',departures:'Abreisen',inhouse:'Im Haus',done:'Erledigt'})[receptionFilter]);set(m,194,746,receptionFilter==='arrivals'?'Check-in durchführen':'Aufenthalte anzeigen');set(w,30,726,rows.length+' Einträge');
 for(let i=0;i<3;i++){const b=shown[i],name=b?get('guests',b.guest).name:'Keine weiteren Einträge',desc=b?'Zimmer '+get('rooms',b.room).number+' · '+b.people+' Personen · '+b.status:'';set(m,71,530+i*69,name);set(m,71,548+i*69,desc);set(w,29,503+i*68,name);set(w,29,522+i*68,desc)}
