let weekOffset=0,roomOffset=0;
function swissDate(value){const text=String(value??'');const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(text);return match?match[3]+'.'+match[2]+'.'+match[1]:text||'–'}
function localDate(d){return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2)}
function openCalendarReservation(room,day){const next=new Date(day+'T12:00:00');next.setDate(next.getDate()+1);const preset={room,arrival:day,departure:localDate(next),adults:1,children:0,meal:'Nur Logis',status:'Bestätigt'};if(window.innerWidth<800)startBooking(preset);else edit('bookings','',preset)}
function calendarChange(id,mode){const b=get('bookings',id);if(!b.id||b.status!=='Bestätigt'||db.invoices.some(i=>i.booking===id))throw Error('Nur bestätigte, nicht abgerechnete Reservationen können hier geändert werden');const move=mode==='room',shorten=mode==='shorten';dialog('<h2>'+(move?'Zimmerwechsel':shorten?'Aufenthalt verkürzen':'Aufenthalt verlängern')+'</h2><p>'+esc(label('bookings',b))+'</p><form id="calendar-change"><label>'+(move?'Neues Zimmer':'Neue Abreise')+'</label>'+(move?'<select name="value" required><option value="">Auswählen</option>'+db.rooms.filter(r=>r.id!==b.room&&r.status!=='Gesperrt'&&!db.bookings.some(x=>x.id!==id&&x.room===r.id&&active(x)&&overlap(x,b))).map(r=>'<option value="'+esc(r.id)+'">'+esc(r.number+' · '+r.category)+'</option>').join('')+'</select>':'<input type="date" name="value" min="'+esc(shorten?b.arrival:b.departure)+'" '+(shorten?'max="'+esc(b.departure)+'" ':'')+'required>')+'<p id="calendar-change-price"></p><div class="actions dialog-actions">'+btn('Abbrechen','close')+'<button type="submit" class="primary">Änderung speichern</button></div></form>');const form=$('calendar-change');const calculate=()=>{const v=form.elements.value.value,n=Object.assign({},b,move?{room:v}:{departure:v});if(!move&&(!v||(shorten?(v<=b.arrival||v>=b.departure):v<=b.departure)))throw Error(shorten?'Neue Abreise muss zwischen Anreise und bisheriger Abreise liegen':'Neue Abreise muss nach bisheriger Abreise liegen');const r=get('rooms',n.room);if(!r.id||r.status==='Gesperrt'||db.bookings.some(x=>x.id!==id&&x.room===r.id&&active(x)&&overlap(x,n)))throw Error('Zimmer nicht verfügbar');if(shorten){const rows=extraMealOverrides(b);n.extraMealDays=Object.keys(rows).sort().filter(day=>day<=n.departure).map(day=>[day,...(day===n.departure?[rows[day][0],0,0]:rows[day])].join(';')).join('\n')}const q=bookingQuote(n,r,db.hotel);if(cents(n.depositAmount||0)>cents(q.total))throw Error('Anzahlung übersteigt neuen Gesamtbetrag');n.priceSnapshot=q;return n};form.addEventListener('change',()=>{try{const n=calculate();$('calendar-change-price').textContent='Neuer Gesamtbetrag: '+money(n.priceSnapshot.total)}catch(e){$('calendar-change-price').textContent=e.message}});form.onsubmit=e=>{e.preventDefault();try{const n=calculate();if(!confirm('Änderung mit neuem Gesamtbetrag '+money(n.priceSnapshot.total)+(shorten?' · Nicht mehr gültige Tagesverpflegung wird entfernt.':'')+' speichern?'))return;atomicChange(()=>{const field=move?'room':'departure';n.changeHistory=(b.changeHistory||[]).concat({date:new Date().toISOString(),changes:[{field,before:String(b[field]),after:String(n[field])}].concat(shorten&&String(b.extraMealDays||'')!==String(n.extraMealDays||'')?[{field:'extraMealDays',before:String(b.extraMealDays||''),after:String(n.extraMealDays||'')}]:[])});Object.assign(b,n)},'Reservation geändert · '+label('bookings',b));close();render()}catch(err){alert(err.message)}}}
function calendarDetail(b){
 const guest=get('guests',b.guest),room=get('rooms',b.room),quote=b.priceSnapshot;
 const sections=[
  ['Aufenthalt',[['Gast',guest.name],['Zimmer',room.number+' · '+(room.category||'')],['Status',b.status],['Anreise',swissDate(b.arrival)],['Abreise',swissDate(b.departure)],['Nächte',nights(b)]]],
  ['Gäste',[['Erwachsene',b.adults||b.people],['Kinder',b.children||0],['Begleitpersonen',b.companions||'–'],['Gruppenreferenz',b.groupRef||'–']]],
  ['Verpflegung',[['Verpflegung',b.meal],['Zusatzfrühstück pro Tag',b.extraBreakfast||0],['Zusatzmittagessen pro Tag',b.extraLunch||0],['Zusatzabendessen pro Tag',b.extraDinner||0],['Tagesabweichungen',b.extraMealDays||'–']]],
  ['Finanzen',[['Vorgesehene Anzahlung',money(b.depositAmount||0)],['Gesamtbetrag',quote?money(quote.total):'–']]]
 ];
 const invoice=db.invoices.find(i=>i.booking===b.id);
 const actions=btn('Gast','edit','guests:'+b.guest)+(b.status==='Eingecheckt'||b.status==='Bestätigt'&&b.arrival<=today()&&today()<b.departure?btn(b.status==='Eingecheckt'?'Check-out':'Check-in','reception',b.id):'')+(invoice?btn('Rechnung','invoice',invoice.id):'')+(b.status==='Bestätigt'&&!invoice?btn('Zimmerwechsel','calendarMove',b.id)+btn('Verlängern','calendarExtend',b.id)+btn('Verkürzen','calendarShorten',b.id):'')+btn('Bearbeiten','edit','bookings:'+b.id,'primary');
 const tabButtons=sections.map(([name],i)=>'<button type="button" role="tab" id="calendar-detail-tab-'+i+'" aria-controls="calendar-detail-panel-'+i+'" aria-selected="'+(i===0)+'" tabindex="'+(i===0?0:-1)+'" class="'+(i===0?'primary':'')+'">'+editorTabIcon(name)+'<span>'+esc(name)+'</span>'+'</button>').join('');
 const panels=sections.map(([name,fields],i)=>'<section class="editor-tab-panel" role="tabpanel" id="calendar-detail-panel-'+i+'" aria-labelledby="calendar-detail-tab-'+i+'" '+(i?'hidden':'')+'><div class="editor-fields">'+fields.map(([key,value])=>'<div class="editor-field"><label>'+esc(key)+'</label><div class="calendar-detail-value">'+esc(value==null?'–':value)+'</div></div>').join('')+'</div></section>').join('');
 dialog('<h2>Reservation · Zimmerkalender</h2><div class="compact-editor columns-3 calendar-detail"><div class="editor-tabs calendar-detail-tabs" role="tablist" aria-label="Reservationsbereiche">'+tabButtons+'</div>'+panels+'<div class="actions dialog-actions calendar-detail-actions">'+actions+'</div></div>');
 const tabs=Array.from($('dialog').querySelectorAll('.calendar-detail-tabs [role="tab"]')),views=Array.from($('dialog').querySelectorAll('.calendar-detail [role="tabpanel"]'));
 const select=index=>{tabs.forEach((tab,i)=>{const current=i===index;tab.setAttribute('aria-selected',String(current));tab.setAttribute('tabindex',current?'0':'-1');tab.classList.toggle('primary',current);views[i].hidden=!current});tabs[index].focus()};
 tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>select(i));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();select(next)})});
}

let calendarCategory='',calendarAvailability='all',calendarSpan=7;
let calendarAnchor='';
