 for(let i=0;i<7;i++){const x=shown[i];set(m,27,284+i*59,x?title(x):'–');set(m,27,303+i*59,x?desc(x):'');keys.forEach((k,j)=>set(m,282+j*33,297+i*59,x?(x[k]?'✓':'–'):''));bind(m.querySelector('text[x="27"][y="'+(284+i*59)+'"]'),()=>{if(x)edit('bookings',x.booking.id)})}
